window.FAQ=(window.FAQ||[]).concat([
 {id:'pnx-001',thema:'pensioen',vraag:'Hoe reken ik de AOW-korting uit bij jaren in het buitenland?',antwoord:`De AOW wordt opgebouwd over de vijftig jaar voor de AOW-leeftijd. Elk verzekerd jaar levert twee procent van de volledige AOW op. Een klant met tien niet-verzekerde jaren krijgt dus tachtig procent van de volledige uitkering. Gebruik voor de exacte opbouw het overzicht van de SVB en niet een eigen schatting.`,tags:['aow','buitenland','opbouw','rekenvoorbeeld'],bron:'SVB'},
 {id:'pnx-002',thema:'pensioen',vraag:'Kan een klant de AOW eerder of later laten ingaan?',antwoord:`Nee, de AOW gaat in op de dag dat de klant de AOW-leeftijd bereikt. Vervroegen of uitstellen is niet mogelijk, anders dan bij het werkgeverspensioen. Wil de klant eerder stoppen, dan moet het inkomen tot de AOW-leeftijd uit andere bronnen komen. Leg vast hoe dit inkomensgat wordt gedekt.`,tags:['aow','vervroegen','uitstellen'],bron:'Algemene Ouderdomswet'},
 {id:'pnx-003',thema:'pensioen',vraag:'Wat is het verschil tussen het AOW-gat en een AOW-hiaat door buitenlandjaren?',antwoord:`Het AOW-gat is een periode zonder AOW, omdat de klant eerder stopt of het pensioen eerder ingaat. Een hiaat door buitenlandjaren is een blijvend lagere AOW, ook na de AOW-leeftijd. Het eerste probleem is tijdelijk, het tweede levenslang. Ze vragen dus een andere oplossing, zoals een overbruggingsuitkering of een levenslange aanvulling.`,tags:['aow','aow-gat','buitenland'],bron:'Algemene Ouderdomswet'},
 {id:'pnx-004',thema:'pensioen',vraag:'Kan een klant ontbrekende AOW-jaren nog repareren?',antwoord:`In sommige situaties kan iemand die Nederland verlaat zich vrijwillig verzekeren voor de AOW. Daarvoor gelden een aanmeldtermijn en een maximale duur. Achteraf repareren van jaren lang geleden is meestal niet meer mogelijk. Verwijs de klant naar de SVB voor de voorwaarden in zijn situatie.`,tags:['aow','vrijwillige verzekering','buitenland'],bron:'SVB'},
 {id:'pnx-005',thema:'pensioen',vraag:'Wat is de AIO-aanvulling en wanneer speelt die?',antwoord:`De AIO-aanvulling is een bijstandsuitkering van de SVB voor AOW-gerechtigden met een onvolledige AOW en weinig ander inkomen. Er geldt een inkomens- en vermogenstoets. Ook een deel van de overwaarde van de eigen woning kan meetellen. Bespreek dit als een klant met veel buitenlandjaren een woning wil kopen of aanhouden.`,tags:['aow','aio','bijstand','vermogenstoets'],bron:'SVB'},
 {id:'pnx-006',thema:'pensioen',vraag:'Telt samenwonen met een volwassen kind mee voor de AOW-norm?',antwoord:`Wonen met een eigen kind of ouder geldt in de AOW niet als gezamenlijke huishouding. De klant houdt dan in principe de AOW voor alleenstaanden. Bij samenwonen met een andere volwassene kan dat anders zijn. Laat de klant de situatie bij de SVB melden en controleer de uitkomst.`,tags:['aow','samenwonen','leefvorm'],bron:'SVB'},
 {id:'pnx-007',thema:'pensioen',vraag:'Wat gebeurt er met de AOW als de klant gaat samenwonen na de AOW-leeftijd?',antwoord:`De klant gaat dan van de AOW voor alleenstaanden naar de AOW voor gehuwden of samenwonenden. Het huishoudinkomen uit AOW stijgt, maar per persoon daalt het bedrag. Dit raakt de betaalbaarheid van lasten die de klant alleen draagt, zoals een hypotheek op eigen naam. Neem dit mee in een advies rond samenwonen op latere leeftijd.`,tags:['aow','samenwonen','betaalbaarheid'],bron:'Algemene Ouderdomswet'},
 {id:'pnx-008',thema:'pensioen',vraag:'Is de kostendelersnorm van toepassing op de AOW?',antwoord:`Nee, de kostendelersnorm geldt niet voor de AOW. Hij kan wel spelen bij de AIO-aanvulling, omdat dat een bijstandsuitkering is. Verwar die twee niet bij de inkomensberekening. Controleer bij een AIO-situatie de actuele regels van de SVB.`,tags:['aow','kostendelersnorm','aio'],bron:'SVB'},
 {id:'pnx-009',thema:'pensioen',vraag:'Wat is de mantelzorguitzondering in de AOW?',antwoord:`Wie samenwoont om mantelzorg te geven of te ontvangen, kan onder voorwaarden toch als alleenstaande gelden. Er moet sprake zijn van zorg die past bij de regels van de SVB. Beide personen moeten in de regel een eigen huishouding kunnen aantonen. Leg vast welke norm in je berekening is gebruikt.`,tags:['aow','mantelzorg','leefvorm'],bron:'SVB'},
 {id:'pnx-010',thema:'pensioen',vraag:'Daalt de AOW als de klant na de AOW-leeftijd blijft werken?',antwoord:`Nee, inkomen uit werk heeft geen invloed op de hoogte van de AOW. Wel betaalt de klant over het totale inkomen belasting. Na de AOW-leeftijd is er geen AOW-premie meer verschuldigd, waardoor de belastingdruk in de eerste schijf lager is. Gebruik de actuele tarieven van de Belastingdienst in de netto-berekening.`,tags:['aow','doorwerken','belasting'],bron:'Belastingdienst'},
 {id:'pnx-011',thema:'pensioen',vraag:'Waarom is het netto inkomen na de AOW-leeftijd vaak hoger dan verwacht?',antwoord:`Na de AOW-leeftijd vervalt de AOW-premie in de eerste schijf. Daarnaast kan de klant recht hebben op de ouderenkorting. Daartegenover staat dat sommige heffingskortingen lager zijn. Reken daarom altijd netto met de actuele tarieven en kortingen en niet met bruto bedragen alleen.`,tags:['aow','netto','belasting','ouderenkorting'],bron:'Belastingdienst'},
 {id:'pnx-012',thema:'pensioen',vraag:'Hoe ga ik om met een jongere partner bij het bereiken van de AOW-leeftijd?',antwoord:`Als de oudste partner de AOW-leeftijd bereikt, krijgt hij AOW voor gehuwden. De jongere partner heeft nog geen AOW. Sinds de afschaffing van de partnertoeslag voor nieuwe gevallen ontstaat zo een inkomensdip. Breng deze periode apart in beeld in de betaalbaarheidsanalyse.`,tags:['aow','leeftijdsverschil','partner','inkomensdip'],bron:'Algemene Ouderdomswet'},
 {id:'pnx-013',thema:'pensioen',vraag:'Wat gebeurt er met de AOW bij overlijden van de partner?',antwoord:`De overblijvende partner gaat van de AOW voor gehuwden naar die voor alleenstaanden. Het huishoudinkomen uit AOW daalt dus. De SVB past de uitkering in de regel aan na de melding van het overlijden. Neem dit mee in de nabestaandenanalyse na de AOW-leeftijd.`,tags:['aow','overlijden','nabestaanden'],bron:'SVB'},
 {id:'pnx-014',thema:'pensioen',vraag:'Hoe vaak wordt de AOW-leeftijd opnieuw vastgesteld?',antwoord:`De AOW-leeftijd wordt jaarlijks vastgesteld voor het jaar dat vijf jaar later ligt. De stijging hangt af van de ontwikkeling van de levensverwachting. Sinds de wetswijziging telt een jaar extra levensverwachting niet meer volledig door. Raadpleeg voor jongere klanten de actuele prognose en presenteer die als onzeker.`,tags:['aow','aow-leeftijd','prognose'],bron:'Algemene Ouderdomswet'},
 {id:'pnx-015',thema:'pensioen',vraag:'Welke fout zie je vaak bij de AOW-datum in adviesrapporten?',antwoord:`Adviseurs gaan soms uit van een ronde leeftijd zoals 67 jaar. De AOW-leeftijd kan echter een aantal maanden hoger liggen en de AOW gaat in op de exacte verjaardag of datum. Een verkeerde datum geeft een fout inkomensbeeld in het overgangsjaar. Gebruik de AOW-datum van de SVB en vermeld de bron in het dossier.`,tags:['aow','aow-datum','fouten','dossier'],bron:'SVB'},
 {id:'pnx-016',thema:'pensioen',vraag:'Wordt de AOW geëxporteerd als de klant emigreert?',antwoord:`De AOW kan in veel gevallen ook in het buitenland worden uitbetaald. De voorwaarden verschillen per land en hangen af van Europese regels en verdragen. Ook de belastingheffing kan veranderen. Verwijs de klant naar de SVB en een fiscalist voor de situatie in het nieuwe woonland.`,tags:['aow','emigratie','export'],bron:'SVB'},
 {id:'pnx-017',thema:'pensioen',vraag:'Hoe verwerk ik de AOW-vakantie-uitkering in de berekening?',antwoord:`De SVB betaalt de vakantie-uitkering van de AOW eenmaal per jaar uit. In jaarbedragen zit dit bedrag doorgaans al verwerkt. Wie maandbedragen gebruikt, moet opletten dat hij het niet vergeet of dubbel telt. Vermeld in het rapport of bedragen inclusief of exclusief vakantie-uitkering zijn.`,tags:['aow','vakantiegeld','berekening'],bron:'SVB'},
 {id:'pnx-018',thema:'pensioen',vraag:'Mag de werkgever een werknemer ontslaan bij het bereiken van de AOW-leeftijd?',antwoord:`Een arbeidsovereenkomst kan bij of na het bereiken van de AOW-leeftijd vaak zonder preventieve toets eindigen. Veel contracten en cao's bevatten daarvoor een pensioenontslagbeding. Ga dus niet automatisch uit van doorwerken na de AOW-leeftijd. Laat de klant de eigen arbeidsvoorwaarden controleren.`,tags:['aow','ontslag','doorwerken'],bron:'Burgerlijk Wetboek'},
 {id:'pnx-019',thema:'pensioen',vraag:'Telt de AOW mee als toetsinkomen bij een hypotheek na de AOW-leeftijd?',antwoord:`Ja, de AOW is een vaste uitkering en telt mee als inkomen. Let op het verschil tussen de AOW voor alleenstaanden en voor samenwonenden. Bij twee aanvragers telt vaak de som van beide uitkeringen. Controleer de acceptatievoorwaarden van de geldverstrekker voor de exacte berekening.`,tags:['aow','toetsinkomen','hypotheek'],bron:'Gedragscode Hypothecaire Financieringen'},
 {id:'pnx-020',thema:'pensioen',vraag:'Wat moet ik vastleggen over de AOW in het klantdossier?',antwoord:`Leg minimaal vast:
- de AOW-datum volgens de SVB;
- het aantal opgebouwde of ontbrekende jaren;
- de leefvorm die in de berekening is gebruikt;
- de datum en bron van de gegevens.
Zo is later te controleren waarop het advies rustte.`,tags:['aow','dossier','vastlegging'],bron:'SVB'},
 {id:'pnx-021',thema:'pensioen',vraag:'Hoe herken ik een klant met een AOW-tekort tijdens de inventarisatie?',antwoord:`Vraag gericht naar wonen, werken of studeren buiten Nederland vanaf jonge leeftijd. Let op klanten die later naar Nederland zijn gekomen en op ex-expats. Het pensioenoverzicht toont de verwachte AOW, maar alleen als de gegevens volledig zijn. Laat bij twijfel een opgave van de SVB opvragen.`,tags:['aow','inventarisatie','buitenland'],bron:'SVB'},
 {id:'pnx-022',thema:'pensioen',vraag:'Bouwt een klant die in het buitenland werkt voor een Nederlandse werkgever AOW op?',antwoord:`Dat hangt af van de situatie, zoals de duur van de detachering en het land. Soms blijft de klant in Nederland verzekerd, soms niet. Een A1-verklaring of verdragsverklaring kan dat bevestigen. Vraag de klant naar deze verklaring en verwijs bij twijfel naar de SVB.`,tags:['aow','detachering','buitenland'],bron:'SVB'},
 {id:'pnx-023',thema:'pensioen',vraag:'Hoe leg ik een klant uit waarom zijn AOW lager is dan bij een kennis?',antwoord:`De hoogte hangt af van het aantal verzekerde jaren en de leefvorm. Twee mensen met dezelfde leeftijd kunnen dus een andere AOW krijgen. Ook de betaaldatum en netto-inhouding kunnen verschillen. Laat de klant het eigen overzicht van de SVB raadplegen en vergelijk niet met anderen.`,tags:['aow','uitleg','klantcommunicatie'],bron:'SVB'},
 {id:'pnx-024',thema:'pensioen',vraag:'Kan een klant afstand doen van de AOW?',antwoord:`Nee, de AOW is een volksverzekering en de klant kan er geen afstand van doen. Ook omzetten in een bedrag ineens is niet mogelijk. Wel kan de leefvorm de hoogte beïnvloeden. Ga in advies dus uit van de wettelijke uitkering.`,tags:['aow','volksverzekering'],bron:'Algemene Ouderdomswet'},
 {id:'pnx-025',thema:'pensioen',vraag:'Waarom moet ik bij AOW-berekeningen rekening houden met de partner van de klant?',antwoord:`De hoogte van de AOW hangt af van de leefvorm van de klant. Een partner beïnvloedt het bedrag, ook als die zelf nog geen AOW heeft. Bij een scheiding of overlijden verandert de uitkering. Neem daarom per scenario de juiste AOW-norm op.`,tags:['aow','partner','scenario'],bron:'Algemene Ouderdomswet'},
 {id:'pnx-026',thema:'pensioen',vraag:'Wat is het verschil tussen opgebouwd en te bereiken pensioen op een overzicht?',antwoord:`Opgebouwd pensioen is wat de klant nu al heeft verworven. Te bereiken pensioen gaat ervan uit dat de klant tot de pensioendatum blijft werken bij dezelfde werkgever met hetzelfde salaris. Bij een baanwissel of minder werken valt het te bereiken bedrag lager uit. Maak in het advies duidelijk welk bedrag je gebruikt.`,tags:['pensioenoverzicht','opgebouwd','te bereiken'],bron:'Pensioenwet'},
 {id:'pnx-027',thema:'pensioen',vraag:'Waarom wijkt de pensioenleeftijd op het overzicht af van de AOW-leeftijd?',antwoord:`Veel regelingen hanteren een eigen standaard pensioenleeftijd. Die kan hoger of lager liggen dan de AOW-leeftijd van de klant. De bedragen op het overzicht gelden dan voor die standaarddatum. Vraag bij de uitvoerder een opgave aan voor de gewenste ingangsdatum.`,tags:['pensioenoverzicht','pensioenleeftijd','aow'],bron:'Pensioenwet'},
 {id:'pnx-028',thema:'pensioen',vraag:'Wat is het Uniform Pensioenoverzicht (UPO)?',antwoord:`Het UPO is het jaarlijkse overzicht dat een pensioenuitvoerder aan actieve deelnemers stuurt. Het toont onder meer opgebouwd en te bereiken pensioen en het nabestaandenpensioen. Door de vaste opzet zijn overzichten van verschillende uitvoerders beter te vergelijken. Vraag de klant om het meest recente UPO van elke regeling.`,tags:['upo','pensioenoverzicht','inventarisatie'],bron:'Pensioenwet'},
 {id:'pnx-029',thema:'pensioen',vraag:'Hoe vaak krijgt een slaper een pensioenoverzicht?',antwoord:`Een gewezen deelnemer krijgt minder vaak een overzicht dan een actieve deelnemer. Daardoor kan de informatie verouderd zijn. Het pensioen kan in de tussentijd zijn verhoogd of verlaagd. Raadpleeg daarom ook de online omgeving van de uitvoerder of vraag een actuele opgave.`,tags:['pensioenoverzicht','slaper','actualiteit'],bron:'Pensioenwet'},
 {id:'pnx-030',thema:'pensioen',vraag:'Staan lijfrentes op mijnpensioenoverzicht.nl?',antwoord:`Mijnpensioenoverzicht.nl toont vooral AOW en pensioen uit werkgeversregelingen. Individuele lijfrentes en bancaire lijfrenteproducten staan er doorgaans niet op. Vraag deze producten daarom apart uit. Anders mist een deel van het oudedagsinkomen in de analyse.`,tags:['mijnpensioenoverzicht','lijfrente','inventarisatie'],bron:'Stichting Pensioenregister'},
 {id:'pnx-031',thema:'pensioen',vraag:'Zijn de bedragen op een pensioenoverzicht bruto of netto?',antwoord:`Pensioenoverzichten tonen bruto bedragen. Het netto inkomen hangt af van belasting, heffingskortingen en de totale inkomenssituatie. Een netto-indicatie op een overzicht is altijd een vereenvoudiging. Maak voor het advies een eigen netto-berekening met de actuele tarieven.`,tags:['pensioenoverzicht','bruto','netto'],bron:'Pensioenwet'},
 {id:'pnx-032',thema:'pensioen',vraag:'Hoe interpreteer ik de drie scenarios op een overzicht van een premieregeling?',antwoord:`Bij een premieregeling toont het overzicht een verwacht, een optimistisch en een pessimistisch bedrag. Deze bedragen zijn uitkomsten van berekeningen met beleggingsscenario's en geen toezegging. Het pessimistische scenario is niet het slechtst denkbare. Leg vast welk scenario je gebruikt en waarom.`,tags:['pensioenoverzicht','scenario','premieregeling'],bron:'Pensioenwet'},
 {id:'pnx-033',thema:'pensioen',vraag:'Welk scenario gebruik ik voor betaalbaarheid na pensionering?',antwoord:`Voor een voorzichtige analyse ligt het pessimistische scenario voor de hand. Het verwachte scenario kan een te rooskleurig beeld geven bij langlopende verplichtingen. Laat ook de gevoeligheid zien als het pensioen lager uitvalt. Leg de gekozen uitgangspunten en de afweging vast in het dossier.`,tags:['pensioenoverzicht','betaalbaarheid','scenario'],bron:'AFM'},
 {id:'pnx-034',thema:'pensioen',vraag:'Zit indexatie in de bedragen op het pensioenoverzicht?',antwoord:`Toekomstige indexatie is meestal niet gegarandeerd en vaak niet opgenomen in het opgebouwde bedrag. In de scenario's kan wel rekening zijn gehouden met inflatie. Lees de toelichting op het overzicht om te zien welk uitgangspunt geldt. Leg uit dat de koopkracht kan afwijken van het getoonde bedrag.`,tags:['pensioenoverzicht','indexatie','koopkracht'],bron:'Pensioenwet'},
 {id:'pnx-035',thema:'pensioen',vraag:'Wat doe ik als een pensioen ontbreekt op mijnpensioenoverzicht.nl?',antwoord:`Vraag de klant naar alle vroegere werkgevers en dienstverbanden. Een pensioen kan ontbreken door een fout in gegevens, een buitenlandse regeling of een kleine aanspraak die is afgekocht of overgedragen. Neem zo nodig contact op met de oude werkgever of uitvoerder. Leg in het dossier vast welke regelingen zijn nagezocht.`,tags:['mijnpensioenoverzicht','ontbrekend','inventarisatie'],bron:'Stichting Pensioenregister'},
 {id:'pnx-036',thema:'pensioen',vraag:'Hoe herken ik op een overzicht of het partnerpensioen op risicobasis is?',antwoord:`Bij risicobasis staat vaak een partnerpensioen dat alleen geldt zolang de klant in dienst is. Bij opbouwbasis staat ook een opgebouwd bedrag dat blijft na uitdiensttreding. Het UPO maakt dit onderscheid meestal zichtbaar. Controleer bij twijfel het pensioenreglement.`,tags:['pensioenoverzicht','partnerpensioen','risicobasis'],bron:'Pensioenwet'},
 {id:'pnx-037',thema:'pensioen',vraag:'Staat een pensioen van de ex-partner op het overzicht van de klant?',antwoord:`Na conversie krijgt de ex-partner een eigen recht, dat op diens eigen overzicht staat. Bij verevening blijft het recht bij de deelnemer en betaalt de uitvoerder een deel uit aan de ex-partner. Het overzicht van de deelnemer kan dan een te hoog beeld geven van wat hij zelf ontvangt. Vraag na een scheiding altijd naar de verdeling.`,tags:['pensioenoverzicht','scheiding','verevening'],bron:'Wet pensioenverdeling bij scheiding'},
 {id:'pnx-038',thema:'pensioen',vraag:'Hoe vergelijk ik pensioenoverzichten met verschillende peildata?',antwoord:`Overzichten kunnen op verschillende momenten zijn opgemaakt. Daardoor lopen opbouw, indexaties en kortingen niet gelijk. Vermeld per regeling de peildatum in je inventarisatie. Bij grote verschillen in datum is een actuele opgave beter.`,tags:['pensioenoverzicht','peildatum','inventarisatie'],bron:'Pensioenwet'},
 {id:'pnx-039',thema:'pensioen',vraag:'Wat betekent een pensioenoverzicht met de vermelding premievrij?',antwoord:`Premievrij betekent dat er geen nieuwe opbouw meer plaatsvindt in die regeling. Het opgebouwde recht blijft staan tot de pensioendatum. Dit is gebruikelijk na uitdiensttreding. Bij arbeidsongeschiktheid kan wel premievrije voortzetting gelden, waarbij de opbouw doorloopt.`,tags:['pensioenoverzicht','premievrij','slaper'],bron:'Pensioenwet'},
 {id:'pnx-040',thema:'pensioen',vraag:'Wat is premievrije voortzetting bij arbeidsongeschiktheid?',antwoord:`Veel regelingen laten de pensioenopbouw doorlopen als een deelnemer arbeidsongeschikt raakt. De deelnemer betaalt dan geen premie over het arbeidsongeschikte deel. Het pensioenoverzicht kan daardoor hoger zijn dan de klant verwacht. Controleer de voorwaarden in het reglement en of de dekking actief is.`,tags:['pensioenoverzicht','arbeidsongeschiktheid','premievrije voortzetting'],bron:'Pensioenwet'},
 {id:'pnx-041',thema:'pensioen',vraag:'Waarom is mijnpensioenoverzicht.nl geen volledig financieel plan?',antwoord:`De site toont pensioen en AOW, maar niet alle inkomsten en uitgaven. Vermogen, lijfrentes, hypotheek en woonlasten ontbreken. Ook de netto-uitkomst is een indicatie. Gebruik de site als bron, maar maak een eigen integrale analyse.`,tags:['mijnpensioenoverzicht','financiele planning'],bron:'Stichting Pensioenregister'},
 {id:'pnx-042',thema:'pensioen',vraag:'Hoe ga ik om met een pensioenoverzicht in buitenlandse valuta?',antwoord:`Een buitenlands pensioen kan in een andere valuta worden uitbetaald. Wisselkoersen veranderen, waardoor de uitkering in euro schommelt. Rekening houden met een voorzichtige koers is verstandig. Leg de gebruikte koers en de datum vast in het dossier.`,tags:['pensioenoverzicht','buitenland','valuta'],bron:''},
 {id:'pnx-043',thema:'pensioen',vraag:'Hoe kan een klant de gegevens op mijnpensioenoverzicht.nl delen met de adviseur?',antwoord:`De klant logt in met DigiD en kan een overzicht downloaden of printen. Sommige adviessoftware kan gegevens inlezen met toestemming van de klant. Laat de klant zelf inloggen en vraag nooit om inloggegevens. Leg vast hoe en wanneer de gegevens zijn ontvangen.`,tags:['mijnpensioenoverzicht','gegevens','privacy'],bron:'Stichting Pensioenregister'},
 {id:'pnx-044',thema:'pensioen',vraag:'Moet ik pensioengegevens bewaren in het dossier?',antwoord:`Ja, bewaar de gegevens waarop het advies is gebaseerd. Zonder bron is achteraf niet te onderbouwen waarom een advies passend was. Houd daarbij rekening met de AVG en bewaar niet meer dan nodig. Volg het bewaarbeleid van je eigen organisatie.`,tags:['dossier','avg','bewaren'],bron:'AVG'},
 {id:'pnx-045',thema:'pensioen',vraag:'Welke fout maken adviseurs vaak met het te bereiken pensioen?',antwoord:`Een veelgemaakte fout is het te bereiken pensioen als zeker inkomen opvoeren. Dat bedrag veronderstelt jarenlang dezelfde baan en hetzelfde salaris. Bij een geplande baanwissel, deeltijd of ondernemerschap valt het lager uit. Werk liever met het opgebouwde pensioen plus een voorzichtige schatting van verdere opbouw.`,tags:['pensioenoverzicht','te bereiken','fouten'],bron:'AFM'},
 {id:'pnx-046',thema:'pensioen',vraag:'Wat zegt een lagere opbouw dan vorig jaar op een overzicht?',antwoord:`Een lager bedrag kan wijzen op een korting, een verdeling na scheiding of een correctie van gegevens. Ook een waardeoverdracht of een afkoop van een klein pensioen kan meespelen. Bij premieregelingen kan het beleggingsresultaat negatief zijn. Vraag de klant of de uitvoerder naar de reden.`,tags:['pensioenoverzicht','korting','controle'],bron:'Pensioenwet'},
 {id:'pnx-047',thema:'pensioen',vraag:'Toont het pensioenoverzicht het wezenpensioen?',antwoord:`Veel overzichten vermelden het wezenpensioen als een regeling dat heeft. De hoogte en de leeftijdsgrenzen staan in het reglement. Het wezenpensioen loopt meestal door tot een bepaalde leeftijd en soms langer bij studie. Neem het mee bij een nabestaandenanalyse met minderjarige of studerende kinderen.`,tags:['pensioenoverzicht','wezenpensioen','nabestaanden'],bron:'Pensioenwet'},
 {id:'pnx-048',thema:'pensioen',vraag:'Hoe gebruik ik pensioenoverzichten bij een klant met meerdere dienstverbanden?',antwoord:`Maak per regeling een aparte regel met uitvoerder, soort regeling en ingangsdatum. Let op verschillende pensioenleeftijden en op dubbel getelde bedragen. Tel daarna het totaal per leeftijdsjaar. Zo ziet de klant per periode welk inkomen hij kan verwachten.`,tags:['pensioenoverzicht','meerdere werkgevers','inventarisatie'],bron:''},
 {id:'pnx-049',thema:'pensioen',vraag:'Wat moet ik doen als de klant geen DigiD heeft?',antwoord:`Zonder DigiD kan de klant mijnpensioenoverzicht.nl niet raadplegen. De klant kan DigiD aanvragen of een machtiging regelen. Je kunt ook rechtstreeks overzichten bij de uitvoerders laten opvragen. Leg vast hoe je de pensioengegevens alsnog hebt verkregen.`,tags:['mijnpensioenoverzicht','digid','machtiging'],bron:'Logius'},
 {id:'pnx-050',thema:'pensioen',vraag:'Hoe controleer ik of een opgebouwde aanspraak al is overgedragen?',antwoord:`Na een waardeoverdracht verdwijnt de aanspraak bij de oude uitvoerder en verschijnt die bij de nieuwe. Op mijnpensioenoverzicht.nl kan dat met vertraging zichtbaar worden. Zo ontstaat het risico dat je een pensioen dubbel telt. Vraag bij twijfel bij beide uitvoerders de status op.`,tags:['waardeoverdracht','pensioenoverzicht','dubbeltelling'],bron:'Pensioenwet'},
 {id:'pnx-051',thema:'pensioen',vraag:'Wat is het verschil tussen een uitkeringsovereenkomst en een premieovereenkomst onder de Wtp?',antwoord:`Onder de Wtp worden nieuwe uitkeringsovereenkomsten in principe niet meer gesloten. Pensioen wordt opgebouwd via een premieovereenkomst. De hoogte van de uitkering staat dan niet vooraf vast. Leg de klant uit dat het pensioen meer afhangt van rendement en renteontwikkeling.`,tags:['wtp','premieovereenkomst','uitkeringsovereenkomst'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-052',thema:'pensioen',vraag:'Wat is een persoonlijk pensioenvermogen?',antwoord:`In de nieuwe regelingen krijgt elke deelnemer een eigen pensioenvermogen toegewezen. In een flexibele regeling is dat een individueel vermogen. In een solidaire regeling wordt het vermogen toegedeeld volgens vaste regels. Het vermogen is een basis voor de uitkering, maar geen spaarrekening die vrij opneembaar is.`,tags:['wtp','pensioenvermogen','toedeling'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-053',thema:'pensioen',vraag:'Wat is de solidariteitsreserve?',antwoord:`De solidariteitsreserve is een buffer binnen een solidaire premieregeling. Uit deze reserve kunnen tegenvallers worden opgevangen of uitkeringen worden gestabiliseerd. De vulling en de inzet zijn vastgelegd in de regeling. Wijs de klant erop dat dit geen garantie geeft op een vast bedrag.`,tags:['wtp','solidariteitsreserve','solidaire regeling'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-054',thema:'pensioen',vraag:'Wat betekent leeftijdsafhankelijk beleggen in een nieuwe regeling?',antwoord:`Jongere deelnemers lopen doorgaans meer beleggingsrisico dan ouderen. Naarmate de pensioendatum nadert, neemt het risico af. In een flexibele regeling gebeurt dit vaak via een lifecycle. In een solidaire regeling verloopt dit via de toedeling van rendement aan leeftijdscohorten.`,tags:['wtp','lifecycle','beleggingsrisico'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-055',thema:'pensioen',vraag:'Waarom kan het pensioen in het nieuwe stelsel sneller meebewegen met de economie?',antwoord:`In de nieuwe contracten zijn minder buffers verplicht dan in het oude stelsel. Mee- en tegenvallers worden daardoor sneller verwerkt in de pensioenvermogens of uitkeringen. Dat geeft meer kans op verhogingen, maar ook op verlagingen. Bespreek met de klant hoe hij met schommelingen in het inkomen kan omgaan.`,tags:['wtp','schommelingen','uitkering'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-056',thema:'pensioen',vraag:'Wat is het verschil tussen een vaste en een variabele uitkering?',antwoord:`Bij een vaste uitkering staat het bedrag vast, eventueel met een afgesproken verhoging. Bij een variabele uitkering wordt na pensionering doorbelegd en kan het bedrag stijgen of dalen. Een variabele uitkering geeft meer kans op koopkrachtbehoud, maar ook risico. Leg de afweging en de risicohouding van de klant vast.`,tags:['wtp','vaste uitkering','variabele uitkering'],bron:'Wet verbeterde premieregeling'},
 {id:'pnx-057',thema:'pensioen',vraag:'Wat is een projectierendement?',antwoord:`Een projectierendement is het verwachte rendement dat wordt gebruikt om een variabele uitkering vast te stellen. Een hoger projectierendement geeft een hogere startuitkering. Daar staat een grotere kans op latere dalingen tegenover. Leg dit uit als de klant moet kiezen tussen uitkeringsvarianten.`,tags:['wtp','projectierendement','variabele uitkering'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-058',thema:'pensioen',vraag:'Wat gebeurt er met de doorsneesystematiek?',antwoord:`In het oude stelsel betaalden alle deelnemers dezelfde premie, terwijl de opbouw voor jongeren relatief duurder was. De Wtp schaft deze systematiek af. Middelbare deelnemers kunnen daardoor nadeel ondervinden in de overgang. Fondsen en werkgevers moeten in hun transitieplan aangeven of en hoe zij dat compenseren.`,tags:['wtp','doorsneesystematiek','compensatie'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-059',thema:'pensioen',vraag:'Wat is een transitieplan?',antwoord:`Een transitieplan beschrijft hoe werkgever en sociale partners overgaan naar een nieuwe regeling. Het gaat onder meer over het nieuwe contract, compensatie en de keuze voor invaren. De uitvoerder werkt dit uit in een implementatieplan. Vraag bij twijfel de klant naar de communicatie van de werkgever of het fonds.`,tags:['wtp','transitieplan','overgang'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-060',thema:'pensioen',vraag:'Kan een individuele deelnemer bezwaar maken tegen invaren?',antwoord:`Een algemeen individueel bezwaarrecht tegen invaren bestaat niet. Het besluit wordt genomen door het fonds na een proces met sociale partners en vertegenwoordigingsorganen. Wel kunnen belanghebbenden via vastgelegde procedures invloed uitoefenen. Verwijs de klant voor zijn situatie naar de communicatie van het fonds.`,tags:['wtp','invaren','bezwaar'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-061',thema:'pensioen',vraag:'Wat moet ik in een adviesdossier vastleggen over de Wtp-overgang?',antwoord:`Leg vast welke regelingen de klant heeft en of deze over gaan naar een nieuw contract. Noteer welke onzekerheid dit geeft voor de verwachte uitkering. Vermeld welke informatie van het fonds of de werkgever is gebruikt. Leg ook vast dat je de klant hebt gewezen op mogelijke schommelingen.`,tags:['wtp','dossier','vastlegging'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-062',thema:'pensioen',vraag:'Verandert het partnerpensioen in het nieuwe stelsel?',antwoord:`De Wtp harmoniseert onder meer het partnerbegrip en de dekking bij overlijden tijdens het dienstverband. Daarbij geldt een maximum gekoppeld aan het pensioengevend salaris. Ook bestaan er regels voor korte doorlopende dekking na uitdiensttreding. Controleer de dekking in de nieuwe regeling van de klant en vergelijk die met de oude.`,tags:['wtp','partnerpensioen','dekking'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-063',thema:'pensioen',vraag:'Waarom is een oude premieregeling met oplopende staffel niet automatisch aangepast?',antwoord:`Voor bestaande deelnemers in premieregelingen met een oplopende staffel geldt overgangsrecht. De werkgever mag die staffel voor hen onder voorwaarden voortzetten. Nieuwe werknemers krijgen dan de vlakke premie. Controleer welke variant voor de klant geldt.`,tags:['wtp','staffel','overgangsrecht'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-064',thema:'pensioen',vraag:'Welke fout maken adviseurs bij pensioenbedragen tijdens de Wtp-overgang?',antwoord:`Een veelgemaakte fout is bedragen uit het oude stelsel als vaste waarde blijven gebruiken. Na invaren kan de uitkering anders uitpakken en meer schommelen. Ook de verhouding tussen ouderdoms- en partnerpensioen kan wijzigen. Werk met actuele informatie en benoem de onzekerheid in het rapport.`,tags:['wtp','fouten','invaren'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-065',thema:'pensioen',vraag:'Hoe leg ik een klant van zestig het verschil uit tussen oud en nieuw stelsel?',antwoord:`Houd het eenvoudig. In het oude stelsel was de uitkering een toezegging met buffers erachter. In het nieuwe stelsel is er een pensioenvermogen en beweegt de uitkering meer met de financiële markten. Voor oudere deelnemers wordt het risico doorgaans beperkt via de toedeling of de lifecycle.`,tags:['wtp','uitleg','klantcommunicatie'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-066',thema:'pensioen',vraag:'Heeft de Wtp gevolgen voor de toets op betaalbaarheid na pensionering?',antwoord:`Ja, omdat de verwachte uitkering minder zeker kan zijn. Gebruik een voorzichtig scenario bij langlopende lasten zoals een hypotheek. Benoem dat schommelingen in beide richtingen mogelijk zijn. Controleer daarnaast de voorwaarden van de geldverstrekker voor het meetellen van pensioeninkomen.`,tags:['wtp','betaalbaarheid','hypotheek'],bron:'AFM'},
 {id:'pnx-067',thema:'pensioen',vraag:'Wat is keuzebegeleiding bij een premieregeling?',antwoord:`De pensioenuitvoerder moet deelnemers helpen bij keuzes, zoals de beleggingsmix en de uitkeringsvorm. Daarbij hoort het uitvragen van onder meer de risicobereidheid. Keuzebegeleiding is iets anders dan persoonlijk financieel advies. Als adviseur kun je de informatie gebruiken, maar je blijft zelf verantwoordelijk voor jouw advies.`,tags:['keuzebegeleiding','premieregeling','uitvoerder'],bron:'Pensioenwet'},
 {id:'pnx-068',thema:'pensioen',vraag:'Gaat het pensioen bij een verzekerde regeling ook over naar het nieuwe stelsel?',antwoord:`Ook bij verzekerde regelingen moet de werkgever de regeling aanpassen aan de Wtp. Voor reeds opgebouwde aanspraken bij een verzekeraar ligt invaren minder voor de hand. Vaak blijven die aanspraken als premievrije rechten staan. Controleer de afspraken bij de werkgever en de verzekeraar.`,tags:['wtp','verzekerde regeling','werkgever'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-069',thema:'pensioen',vraag:'Moet een werkgever werknemers informeren over de nieuwe regeling?',antwoord:`Ja, de werkgever en de uitvoerder hebben informatieplichten. Werknemers moeten begrijpen wat de nieuwe regeling voor hen betekent. Bij een premieregeling hoort daar ook informatie over risico's bij. Vraag de klant naar deze stukken voor je analyse.`,tags:['wtp','informatieplicht','werkgever'],bron:'Pensioenwet'},
 {id:'pnx-070',thema:'pensioen',vraag:'Wat betekent het nieuwe stelsel voor een zzp-er?',antwoord:`De Wtp gaat primair over werkgeversregelingen. Een zzp-er bouwt meestal geen pensioen op via een werkgever. Wel kan een zzp-er zelf voorzien via lijfrente of een vrijwillige regeling. Bespreek de mogelijkheden en controleer de actuele fiscale ruimte.`,tags:['wtp','zzp','lijfrente'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-071',thema:'pensioen',vraag:'Wat is de compensatie voor de afschaffing van de doorsneesystematiek?',antwoord:`Werkgevers en fondsen kunnen besluiten tot compensatie voor deelnemers die nadeel hebben van de overstap. Hoe dat gebeurt, verschilt per regeling. Het kan gaan om extra premie of een toekenning uit het fondsvermogen. Kijk in de communicatie van de werkgever of het fonds wat voor de klant is afgesproken.`,tags:['wtp','compensatie','overgang'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-072',thema:'pensioen',vraag:'Hoe beïnvloedt rente de uitkering in een flexibele premieregeling?',antwoord:`Bij aankoop van een vaste uitkering bepaalt de rente op dat moment hoeveel uitkering het vermogen oplevert. Een lage rente geeft een lagere uitkering. Daarom wordt het renterisico vaak al voor de pensioendatum afgedekt. Laat in je advies zien dat de uitkomst afhangt van de omstandigheden op de ingangsdatum.`,tags:['wtp','rente','premieregeling'],bron:'Wet verbeterde premieregeling'},
 {id:'pnx-073',thema:'pensioen',vraag:'Mag een klant in een premieregeling kiezen voor een eigen beleggingsprofiel?',antwoord:`Veel premieregelingen bieden enkele profielen met meer of minder risico. Of een eigen keuze mogelijk is, hangt af van de regeling. Een te risicovol profiel vlak voor pensionering kan het inkomen sterk raken. Toets het profiel aan de beleggingshorizon en risicobereidheid van de klant.`,tags:['premieregeling','beleggingsprofiel','risicobereidheid'],bron:'Pensioenwet'},
 {id:'pnx-074',thema:'pensioen',vraag:'Is een pensioen in het nieuwe stelsel nog levenslang?',antwoord:`Ja, ook in het nieuwe stelsel is het ouderdomspensioen een levenslange uitkering. De hoogte kan wel meer variëren dan voorheen. Het langlevenrisico wordt collectief gedeeld. Leg uit dat levenslang niet hetzelfde is als een vast bedrag.`,tags:['wtp','levenslang','langlevenrisico'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-075',thema:'pensioen',vraag:'Hoe vaak verandert een variabele uitkering?',antwoord:`Dat hangt af van de regeling. Veel uitvoerders passen de uitkering eenmaal per jaar aan. Soms worden schokken over meerdere jaren gespreid. Lees het reglement of de keuzebegeleiding van de uitvoerder voor de exacte werkwijze.`,tags:['variabele uitkering','aanpassing','spreiding'],bron:'Wet verbeterde premieregeling'},
 {id:'pnx-076',thema:'pensioen',vraag:'Wat is het belang van de transitiedatum voor een klant die bijna met pensioen gaat?',antwoord:`Een klant die vlak voor of na de overgang met pensioen gaat, kan te maken krijgen met een andere systematiek dan verwacht. Keuzes zoals vervroegen of een bedrag ineens kunnen anders uitpakken. Vraag de uitvoerder naar de gevolgen voor de gewenste ingangsdatum. Leg in het dossier vast welke informatie je hebt gekregen.`,tags:['wtp','transitie','pensioendatum'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-077',thema:'pensioen',vraag:'Kan een werkgever de pensioenregeling eenzijdig wijzigen naar het nieuwe stelsel?',antwoord:`Bij een verplicht bedrijfstakpensioenfonds besluiten sociale partners en het fonds. Bij een eigen regeling moet de werkgever afspraken maken met vakbonden of de ondernemingsraad. Voor wijziging van individuele arbeidsvoorwaarden gelden de regels van het arbeidsrecht. Verwijs bij twijfel naar een arbeidsrechtjurist.`,tags:['wtp','werkgever','instemming'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-078',thema:'pensioen',vraag:'Wat moet ik doen als de klant de informatie over de Wtp niet begrijpt?',antwoord:`Neem de tijd om de belangrijkste gevolgen te benoemen in gewone taal. Gebruik de eigen overzichten van de klant als voorbeeld. Check of de klant het heeft begrepen door hem de kern te laten samenvatten. Leg in het dossier vast welke uitleg is gegeven.`,tags:['wtp','uitleg','klantbegrip'],bron:''},
 {id:'pnx-079',thema:'pensioen',vraag:'Kunnen opgebouwde rechten in het nieuwe stelsel nog worden gekort?',antwoord:`In het nieuwe stelsel wordt niet meer gesproken van korten in de oude betekenis. Wel kan het pensioenvermogen of de uitkering dalen door tegenvallende resultaten. Voor de klant voelt dat hetzelfde. Benoem dit risico in je advies en vermijd beloftes over vaste bedragen.`,tags:['wtp','verlaging','risico'],bron:'Wet toekomst pensioenen'},
 {id:'pnx-080',thema:'pensioen',vraag:'Wat is het verschil tussen vervroegen en deeltijdpensioen?',antwoord:`Bij vervroegen gaat het volledige pensioen eerder in en wordt het levenslang lager. Bij deeltijdpensioen gaat een deel eerder in, terwijl de klant gedeeltelijk blijft werken. Over het resterende deel loopt in de regel opbouw door. Controleer bij de uitvoerder of en hoe deeltijdpensioen mogelijk is.`,tags:['deeltijdpensioen','vervroegen','keuzes'],bron:'Pensioenwet'},
 {id:'pnx-081',thema:'pensioen',vraag:'Hoe ziet een rekenvoorbeeld van vervroegen eruit zonder actuele factoren?',antwoord:`Stel dat een klant zijn pensioen enkele jaren eerder laat ingaan. Het opgebouwde kapitaal moet dan langer uitkeren, terwijl er geen opbouw meer bijkomt. Daardoor wordt de jaarlijkse uitkering levenslang lager. De exacte verlaging volgt uit de factoren van de uitvoerder, dus vraag altijd een opgave.`,tags:['vervroegen','rekenvoorbeeld','uitvoerder'],bron:'Pensioenwet'},
 {id:'pnx-082',thema:'pensioen',vraag:'Is uitstel van pensioen ook mogelijk als de klant niet doorwerkt?',antwoord:`Dat hangt af van het reglement en de fiscale regels. Uitstel is vaak gekoppeld aan doorwerken. Er gelden fiscale grenzen aan de leeftijd waarop het pensioen uiterlijk moet ingaan. Controleer de voorwaarden bij de uitvoerder.`,tags:['uitstellen','keuzes','voorwaarden'],bron:'Pensioenwet'},
 {id:'pnx-083',thema:'pensioen',vraag:'Wat is uitruil van ouderdomspensioen naar partnerpensioen?',antwoord:`Bij uitruil ruilt de deelnemer een deel van het ouderdomspensioen in voor een hoger partnerpensioen. Het ouderdomspensioen wordt dan lager. Uitruil kan ook andersom, van partnerpensioen naar ouderdomspensioen. Bij uitruil naar ouderdomspensioen moet de partner in de regel schriftelijk toestemmen.`,tags:['uitruil','partnerpensioen','ouderdomspensioen'],bron:'Pensioenwet'},
 {id:'pnx-084',thema:'pensioen',vraag:'Wanneer is uitruil van partnerpensioen naar ouderdomspensioen verstandig te bespreken?',antwoord:`Dit speelt als de partner zelf voldoende inkomen heeft of er geen partner is. De klant krijgt dan een hoger eigen pensioen. Het nabestaandenrisico wordt wel groter. Leg de afweging en de handtekening van de partner vast in het dossier.`,tags:['uitruil','partnerpensioen','afweging'],bron:'Pensioenwet'},
 {id:'pnx-085',thema:'pensioen',vraag:'Wat is een veelgemaakte fout bij de keuze voor een hoog-laagconstructie?',antwoord:`Klanten kiezen soms voor een hoge uitkering zonder te kijken naar de lagere periode daarna. De lagere uitkering is levenslang. Vaste lasten zoals een hypotheek lopen dan mogelijk door. Laat de inkomens per periode zien en leg vast dat de klant dit heeft begrepen.`,tags:['hoog-laag','fouten','betaalbaarheid'],bron:'Pensioenwet'},
 {id:'pnx-086',thema:'pensioen',vraag:'Wat is een laag-hoogconstructie?',antwoord:`Bij laag-hoog begint de uitkering lager en wordt deze daarna hoger. Dit kan passen bij een klant die in de eerste jaren nog ander inkomen heeft. Niet elke uitvoerder biedt deze variant aan. Er gelden fiscale grenzen aan de verhouding tussen hoog en laag.`,tags:['laag-hoog','keuzes','uitvoerder'],bron:'Pensioenwet'},
 {id:'pnx-087',thema:'pensioen',vraag:'Kan een klant meerdere keuzes combineren, zoals vervroegen en hoog-laag?',antwoord:`Vaak kunnen keuzes worden gecombineerd, zoals vervroegen, uitruil en hoog-laag. De uitvoerder bepaalt welke combinaties mogelijk zijn. Elke keuze beïnvloedt de hoogte van de andere uitkeringen. Vraag een integrale opgave van de uitvoerder voordat je een advies geeft.`,tags:['keuzes','combinatie','uitvoerder'],bron:'Pensioenwet'},
 {id:'pnx-088',thema:'pensioen',vraag:'Wanneer moet een klant zijn keuzes bij de uitvoerder doorgeven?',antwoord:`Uitvoerders sturen enige tijd voor de pensioendatum een keuzeformulier of verzoek. Daarin staat een uiterste datum. Wie te laat reageert, krijgt vaak de standaardvariant. Start het gesprek daarom ruim voor de pensioendatum.`,tags:['keuzes','termijn','pensioendatum'],bron:'Pensioenwet'},
 {id:'pnx-089',thema:'pensioen',vraag:'Is een gemaakte pensioenkeuze terug te draaien?',antwoord:`Na de ingang van het pensioen zijn de meeste keuzes definitief. Denk aan uitruil, hoog-laag of een bedrag ineens. Daarom is een goede voorbereiding belangrijk. Leg in het dossier vast dat de klant is gewezen op het onomkeerbare karakter.`,tags:['keuzes','onomkeerbaar','dossier'],bron:'Pensioenwet'},
 {id:'pnx-090',thema:'pensioen',vraag:'Welke invloed heeft een bedrag ineens op toeslagen?',antwoord:`Een bedrag ineens telt mee als inkomen in het jaar van opname. Daardoor kunnen toeslagen of inkomensafhankelijke regelingen in dat jaar lager uitvallen. Ook de belastingdruk kan hoger zijn. Bereken de netto-uitkomst en de gevolgen voor toeslagen voordat de klant kiest.`,tags:['bedrag ineens','toeslagen','belasting'],bron:'Belastingdienst'},
 {id:'pnx-091',thema:'pensioen',vraag:'Op welk moment kan een bedrag ineens worden opgenomen?',antwoord:`Het bedrag ineens kan in principe alleen bij de ingang van het ouderdomspensioen worden gekozen. Er gelden regels over het moment van uitbetaling, waarbij de uitvoerder soms een later moment toestaat. De keuze kan gevolgen hebben voor belasting en toeslagen. Controleer de exacte mogelijkheden bij de uitvoerder.`,tags:['bedrag ineens','moment','uitvoerder'],bron:'Pensioenwet'},
 {id:'pnx-092',thema:'pensioen',vraag:'Welke klanten hebben meer risico bij het opnemen van een bedrag ineens?',antwoord:`Klanten met een laag pensioen of een krappe begroting lopen meer risico. Het levenslange pensioen wordt lager door de opname. Ook klanten met toeslagen of een hypotheek na pensionering moeten goed rekenen. Leg de doelbesteding en de gevolgen vast in het dossier.`,tags:['bedrag ineens','risico','doelgroep'],bron:'AFM'},
 {id:'pnx-093',thema:'pensioen',vraag:'Mag een bedrag ineens worden gebruikt om de hypotheek af te lossen?',antwoord:`Dat is mogelijk, want het bedrag ineens is vrij besteedbaar na belasting. Aflossing verlaagt de woonlasten, maar ook het levenslange pensioen. Vergelijk de netto lastenverlichting met het lagere pensioen en het eventuele verlies van renteaftrek. Controleer de voorwaarden van de geldverstrekker voor boetevrij aflossen.`,tags:['bedrag ineens','aflossen','hypotheek'],bron:'Pensioenwet'},
 {id:'pnx-094',thema:'pensioen',vraag:'Hoe beïnvloedt een bedrag ineens het partnerpensioen?',antwoord:`Het bedrag ineens wordt opgenomen uit het ouderdomspensioen. Het partnerpensioen blijft in de regel buiten de opname. Wel kunnen andere keuzes zoals uitruil het partnerpensioen beïnvloeden. Vraag de uitvoerder naar de effecten van de gecombineerde keuzes.`,tags:['bedrag ineens','partnerpensioen'],bron:'Pensioenwet'},
 {id:'pnx-095',thema:'pensioen',vraag:'Wanneer is waardeoverdracht minder aantrekkelijk?',antwoord:`Waardeoverdracht kan nadelig zijn als de oude regeling betere voorwaarden heeft, zoals een hogere indexatie of een gunstiger partnerpensioen. Ook kan de dekking voor nabestaanden veranderen. Vergelijk de regelingen op meer dan alleen het bedrag. Leg de vergelijking vast in het dossier.`,tags:['waardeoverdracht','vergelijking','nadelen'],bron:'Pensioenwet'},
 {id:'pnx-096',thema:'pensioen',vraag:'Hoe lang heeft een werknemer om waardeoverdracht aan te vragen?',antwoord:`Een werknemer kan na indiensttreding binnen een bepaalde termijn waardeoverdracht aanvragen. In veel gevallen zijn er ook latere mogelijkheden. Na de overgang naar het nieuwe stelsel kunnen andere regels gelden. Controleer de actuele termijnen bij de uitvoerder.`,tags:['waardeoverdracht','termijn'],bron:'Pensioenwet'},
 {id:'pnx-097',thema:'pensioen',vraag:'Kan een pensioen uit het buitenland worden overgedragen naar Nederland?',antwoord:`Binnen de EU zijn er mogelijkheden, maar daaraan zijn voorwaarden verbonden. Bij landen buiten de EU is overdracht vaak beperkt. Fiscale gevolgen zijn per situatie verschillend. Verwijs naar een specialist en de uitvoerder.`,tags:['waardeoverdracht','buitenland'],bron:'Pensioenwet'},
 {id:'pnx-098',thema:'pensioen',vraag:'Hoe leg ik een pensioenkeuze vast in het adviesdossier?',antwoord:`Beschrijf de beschikbare keuzes en de gevolgen per keuze. Noteer de wensen, de financiële positie en de risicobereidheid van de klant. Leg de uiteindelijke keuze en de motivering vast. Bewaar de opgaven van de uitvoerder en eventuele handtekeningen van de partner.`,tags:['keuzes','dossier','vastlegging'],bron:'Wft'},
 {id:'pnx-099',thema:'pensioen',vraag:'Kan een klant zijn pensioen bij de ene uitvoerder vervroegen en bij de andere niet?',antwoord:`Ja, elke regeling heeft eigen keuzemogelijkheden en kan afzonderlijk ingaan. Zo kan de klant het inkomen per periode beter afstemmen. Let wel op de verschillende factoren en voorwaarden per uitvoerder. Breng de combinatie in een tijdlijn in beeld.`,tags:['vervroegen','meerdere uitvoerders','tijdlijn'],bron:'Pensioenwet'},
 {id:'pnx-100',thema:'pensioen',vraag:'Wat is het risico van een pensioenkeuze maken zonder partner aan tafel?',antwoord:`Veel keuzes raken ook het inkomen van de partner, vooral uitruil en hoog-laag. Bij uitruil van partnerpensioen is toestemming van de partner bovendien vereist. Een keuze zonder overleg kan later tot problemen leiden. Nodig de partner uit voor het gesprek en leg vast wie aanwezig was.`,tags:['keuzes','partner','gesprek'],bron:'Pensioenwet'},
 {id:'pnx-101',thema:'pensioen',vraag:'Hoe bereid ik een klant voor op het pensioenkeuzegesprek met de uitvoerder?',antwoord:`Laat de klant vooraf zijn overzichten, keuzeformulier en eventuele opgaven verzamelen. Bespreek welke keuzes er zijn en wat de klant belangrijk vindt. Maak een overzicht van het netto inkomen per periode. Zo kan de klant gerichter vragen stellen aan de uitvoerder.`,tags:['keuzes','voorbereiding','uitvoerder'],bron:''},
 {id:'pnx-102',thema:'pensioen',vraag:'Hoe ga ik om met een klant die het pensioen wil vervroegen vanwege gezondheid?',antwoord:`Een slechte gezondheid kan een reden zijn om eerder van het pensioen te willen genieten. Vervroegen verlaagt wel de levenslange uitkering, ook voor een eventuele partner. Bekijk of er andere regelingen zijn, zoals arbeidsongeschiktheidsuitkeringen. Leg de afweging en de motivering vast in het dossier.`,tags:['vervroegen','gezondheid','afweging'],bron:''},
 {id:'pnx-103',thema:'pensioen',vraag:'Wat is een regeling voor vervroegde uittreding (RVU)?',antwoord:`Een RVU is een regeling waarmee een werkgever een werknemer laat stoppen voor de AOW-leeftijd met een uitkering. Fiscaal gelden hiervoor speciale regels en mogelijk een eindheffing voor de werkgever. Er bestaan voorwaarden en vrijstellingen die in de tijd kunnen wijzigen. Controleer de actuele regels bij de Belastingdienst en in de cao.`,tags:['rvu','vervroegen','werkgever'],bron:'Belastingdienst'},
 {id:'pnx-104',thema:'pensioen',vraag:'Hoe vergelijk ik een overbruggingsuitkering met vervroegd pensioen?',antwoord:`Een overbruggingsuitkering is tijdelijk en loopt vaak tot de AOW-leeftijd. Vervroegd pensioen geeft een levenslang lagere uitkering. De keuze hangt af van hoe lang het gat duurt en hoe de klant na de AOW-leeftijd uitkomt. Laat beide varianten naast elkaar zien in een inkomensoverzicht.`,tags:['overbrugging','vervroegen','vergelijking'],bron:'Pensioenwet'},
 {id:'pnx-105',thema:'pensioen',vraag:'Mag een klant na pensioeningang nog werken bij dezelfde werkgever?',antwoord:`Dat is vaak mogelijk, maar het reglement en de cao kunnen voorwaarden stellen. Bij deeltijdpensioen werkt de klant juist gedeeltelijk door. Werken na pensioeningang heeft fiscale gevolgen voor het totale inkomen. Controleer de afspraken met de werkgever en de uitvoerder.`,tags:['doorwerken','pensioeningang','werkgever'],bron:'Pensioenwet'},
 {id:'pnx-106',thema:'pensioen',vraag:'Hoe leg ik een klant uit wat het effect is van later laten ingaan?',antwoord:`Bij uitstel heeft het kapitaal een kortere uitkeringsperiode en kan er nog opbouw bijkomen. Daardoor wordt de uitkering levenslang hoger. De klant ontvangt wel enige tijd geen pensioen. Laat zien vanaf welke leeftijd het totaal ontvangen bedrag hoger uitkomt, met een voorbehoud.`,tags:['uitstellen','uitleg','rekenvoorbeeld'],bron:'Pensioenwet'},
 {id:'pnx-107',thema:'pensioen',vraag:'Kan een klant een klein pensioen laten afkopen?',antwoord:`Kleine pensioenen kunnen onder voorwaarden worden afgekocht. Sinds de wetswijziging worden kleine pensioenen bij uitdiensttreding vaak automatisch overgedragen. Afkoop op of na de pensioendatum is in bepaalde gevallen nog mogelijk. De afkoopgrens wordt jaarlijks vastgesteld, controleer het actuele bedrag.`,tags:['klein pensioen','afkoop','waardeoverdracht'],bron:'Pensioenwet'},
 {id:'pnx-108',thema:'pensioen',vraag:'Welke rol speelt de levensverwachting van de klant bij pensioenkeuzes?',antwoord:`De klant weet niet hoe lang hij leeft. Een keuze als vervroegen of hoog-laag pakt anders uit bij een kort of lang leven. Pensioen is bedoeld om het langlevenrisico te dekken. Benoem dit expliciet en leg vast dat de klant dit risico heeft afgewogen.`,tags:['levensverwachting','keuzes','langleven'],bron:''},
 {id:'pnx-109',thema:'pensioen',vraag:'Hoe adviseer ik als de klant geen informatie van de uitvoerder heeft ontvangen?',antwoord:`Laat de klant zelf contact opnemen met de uitvoerder of doe dat met machtiging. Vraag een opgave van de keuzemogelijkheden en de bedragen. Zonder actuele gegevens kun je geen onderbouwd advies geven. Leg vast welke informatie ontbrak en welke acties zijn ondernomen.`,tags:['uitvoerder','gegevens','dossier'],bron:''},
 {id:'pnx-110',thema:'pensioen',vraag:'Wat zijn signalen dat een klant een pensioenkeuze onder druk maakt?',antwoord:`Let op haast, druk van familie of een acute financiële zorg. Ook een klant die alleen naar het bedrag ineens kijkt, verdient extra aandacht. Neem de tijd om de lange termijn te bespreken. Leg in het dossier vast hoe je de wensen van de klant hebt getoetst.`,tags:['keuzes','zorgplicht','kwetsbaarheid'],bron:'AFM'},
 {id:'pnx-111',thema:'pensioen',vraag:'Welke regeling geldt bij een scheiding vanaf medio 2022?',antwoord:`Voor scheidingen vanaf de inwerkingtreding van de Wet pensioenverdeling bij scheiding geldt in principe conversie. De ex-partner krijgt dan een eigen recht op het verdeelde ouderdomspensioen. Partners kunnen afwijkende afspraken maken. Voor oudere scheidingen blijft de vorige wet van toepassing.`,tags:['scheiding','conversie','pensioenverdeling'],bron:'Wet pensioenverdeling bij scheiding'},
 {id:'pnx-112',thema:'pensioen',vraag:'Binnen welke termijn moet een scheiding bij de uitvoerder worden gemeld?',antwoord:`De scheiding moet binnen twee jaar bij de pensioenuitvoerder worden gemeld. Gebeurt dat niet, dan voert de uitvoerder de verdeling niet zelf uit. De ex-partner moet dan zijn recht via de andere partner proberen te halen. Wijs de klant op deze termijn en leg dat vast.`,tags:['scheiding','melding','termijn'],bron:'Wet pensioenverdeling bij scheiding'},
 {id:'pnx-113',thema:'pensioen',vraag:'Wat gebeurt er bij verevening als de deelnemer overlijdt?',antwoord:`Bij verevening loopt de uitkering aan de ex-partner via het pensioen van de deelnemer. Overlijdt de deelnemer, dan stopt die vereveningsuitkering. De ex-partner kan dan wel recht hebben op bijzonder partnerpensioen. Controleer welk recht de ex-partner heeft.`,tags:['scheiding','verevening','overlijden'],bron:'Wet verevening pensioenrechten bij scheiding'},
 {id:'pnx-114',thema:'pensioen',vraag:'Wat gebeurt er bij verevening als de ex-partner eerder overlijdt?',antwoord:`Bij verevening gaat het deel van de ex-partner na diens overlijden in de regel terug naar de deelnemer. Bij conversie is dat anders, omdat de ex-partner een eigen recht heeft. Dit verschil kan grote gevolgen hebben voor het inkomen van de deelnemer. Leg uit welk systeem voor de klant geldt.`,tags:['scheiding','verevening','conversie'],bron:'Wet verevening pensioenrechten bij scheiding'},
 {id:'pnx-115',thema:'pensioen',vraag:'Over welke periode wordt pensioen verdeeld bij scheiding?',antwoord:`Alleen het pensioen dat is opgebouwd tijdens het huwelijk of geregistreerd partnerschap wordt verdeeld. Pensioen van voor of na die periode valt erbuiten. De uitvoerder stelt het te verdelen deel vast op basis van de gegevens. Controleer de periode op het overzicht van de uitvoerder.`,tags:['scheiding','periode','opbouw'],bron:'Wet pensioenverdeling bij scheiding'},
 {id:'pnx-116',thema:'pensioen',vraag:'Wordt pensioen verdeeld bij beëindiging van samenwonen?',antwoord:`De wettelijke pensioenverdeling geldt voor huwelijk en geregistreerd partnerschap. Voor ongehuwd samenwonenden geldt die niet automatisch. Een samenlevingscontract kan wel afspraken bevatten. Controleer de afspraken en verwijs bij twijfel naar een jurist.`,tags:['scheiding','samenwonen','samenlevingscontract'],bron:'Wet pensioenverdeling bij scheiding'},
 {id:'pnx-117',thema:'pensioen',vraag:'Valt lijfrente onder de pensioenverdeling bij scheiding?',antwoord:`Lijfrenteproducten vallen in de regel niet onder de wettelijke pensioenverdeling. Ze worden verdeeld volgens het huwelijksvermogensrecht of de huwelijkse voorwaarden. Bij verdeling gelden fiscale regels om niet-toegestane handelingen te voorkomen. Laat de verdeling fiscaal zorgvuldig uitvoeren.`,tags:['scheiding','lijfrente','huwelijksvermogensrecht'],bron:'Wet IB 2001'},
 {id:'pnx-118',thema:'pensioen',vraag:'Wordt de AOW verdeeld bij scheiding?',antwoord:`Nee, de AOW is een persoonlijke volksverzekering en wordt niet verdeeld. Wel verandert de AOW-norm na de scheiding. De klant krijgt vanaf de AOW-leeftijd de uitkering voor alleenstaanden, tenzij hij weer samenwoont. Verwerk dat in de berekening na scheiding.`,tags:['scheiding','aow'],bron:'Algemene Ouderdomswet'},
 {id:'pnx-119',thema:'pensioen',vraag:'Hoe beïnvloedt pensioenverdeling de hypotheek na scheiding?',antwoord:`Na verdeling heeft de deelnemer minder pensioen en de ex-partner meer. Dat beïnvloedt de betaalbaarheid na pensionering voor beide. Bij een overname van de woning moet je met het pensioen na verdeling rekenen. Controleer de voorwaarden van de geldverstrekker voor inkomen bij een scheidingssituatie.`,tags:['scheiding','hypotheek','betaalbaarheid'],bron:'Gedragscode Hypothecaire Financieringen'},
 {id:'pnx-120',thema:'pensioen',vraag:'Kunnen ex-partners afspreken dat pensioen niet wordt verdeeld?',antwoord:`Ja, partners kunnen in huwelijkse voorwaarden of een convenant afwijkende afspraken maken. Dat kan uitsluiting van verdeling of een ander percentage betreffen. Zulke afspraken hebben grote gevolgen voor beide partijen. Verwijs naar een jurist of mediator en leg vast dat de klant is geïnformeerd.`,tags:['scheiding','afspraken','convenant'],bron:'Wet pensioenverdeling bij scheiding'},
 {id:'pnx-121',thema:'pensioen',vraag:'Wat is bijzonder partnerpensioen?',antwoord:`Bijzonder partnerpensioen is het partnerpensioen dat de ex-partner houdt na de scheiding. Het gaat om het partnerpensioen dat tijdens het huwelijk is opgebouwd. Bij risicobasis kan het recht beperkt zijn. Controleer het reglement en het overzicht van de uitvoerder.`,tags:['scheiding','bijzonder partnerpensioen'],bron:'Pensioenwet'},
 {id:'pnx-122',thema:'pensioen',vraag:'Wat betekent bijzonder partnerpensioen voor een nieuwe partner?',antwoord:`Het bijzonder partnerpensioen voor de ex-partner gaat af van het partnerpensioen. Een nieuwe partner krijgt daardoor minder dan op het overzicht lijkt. Dit is een veelgemaakte fout bij een nabestaandenanalyse. Vraag het actuele partnerpensioen na scheiding op bij de uitvoerder.`,tags:['scheiding','bijzonder partnerpensioen','nieuwe partner'],bron:'Pensioenwet'},
 {id:'pnx-123',thema:'pensioen',vraag:'Kan een ex-partner afstand doen van bijzonder partnerpensioen?',antwoord:`Ex-partners kunnen afspreken dat het bijzonder partnerpensioen vervalt. Dat moet wel correct worden vastgelegd en aan de uitvoerder worden doorgegeven. Dan kan het partnerpensioen ten goede komen aan een nieuwe partner. Controleer de procedure en eventuele voorwaarden bij de uitvoerder.`,tags:['scheiding','bijzonder partnerpensioen','afstand'],bron:'Pensioenwet'},
 {id:'pnx-124',thema:'pensioen',vraag:'Hoe zit het met pensioenverdeling bij een DGA met pensioen in eigen beheer?',antwoord:`Ook pensioen in eigen beheer of een oudedagsverplichting kan bij scheiding verdeeld moeten worden. De uitvoering ligt dan bij de BV en dat geeft vaak extra complexiteit. Waardering en uitvoering vragen specialistische kennis. Verwijs naar een gespecialiseerde fiscalist of jurist.`,tags:['scheiding','dga','eigen beheer'],bron:'Wet pensioenverdeling bij scheiding'},
 {id:'pnx-125',thema:'pensioen',vraag:'Wat is een veelgemaakte fout bij het inventariseren van pensioen na een scheiding?',antwoord:`Adviseurs nemen soms het volle bedrag van het overzicht op, terwijl een deel aan de ex-partner toekomt. Bij verevening is dat niet altijd zichtbaar op het overzicht. Vraag daarom altijd naar eerdere huwelijken en scheidingen. Leg de gegevens van de verdeling vast in het dossier.`,tags:['scheiding','inventarisatie','fouten'],bron:''},
 {id:'pnx-126',thema:'pensioen',vraag:'Hoe verdeel ik pensioen bij een scheiding na de pensioeningang?',antwoord:`Ook een al ingegaan pensioen kan worden verdeeld als het tijdens het huwelijk is opgebouwd. De uitvoerder past dan de lopende uitkering aan. De gevolgen voor het netto inkomen kunnen direct groot zijn. Bereken de nieuwe situatie voor beide ex-partners.`,tags:['scheiding','ingegaan pensioen','verdeling'],bron:'Wet pensioenverdeling bij scheiding'},
 {id:'pnx-127',thema:'pensioen',vraag:'Wat moet ik doen bij een scheiding met een buitenlands pensioen?',antwoord:`De Nederlandse wetgeving geldt niet automatisch voor buitenlandse pensioenen. De verdeling kan volgen uit buitenlands recht of afspraken tussen partijen. Dat vraagt specialistische kennis. Verwijs naar een jurist en leg de afspraken vast.`,tags:['scheiding','buitenland','pensioenverdeling'],bron:''},
 {id:'pnx-128',thema:'pensioen',vraag:'Moet ik het nabestaandenrisico opnieuw beoordelen na een scheiding?',antwoord:`Ja, na een scheiding verandert de nabestaandensituatie sterk. Een ex-partner kan nog recht hebben op bijzonder partnerpensioen of een ORV-uitkering. Kinderen hebben mogelijk recht op wezenpensioen. Controleer ook de begunstiging van verzekeringen en pas die zo nodig aan.`,tags:['scheiding','nabestaanden','begunstiging'],bron:''},
 {id:'pnx-129',thema:'pensioen',vraag:'Voert de uitvoerder een convenant uit dat afwijkt van de standaardverdeling?',antwoord:`De uitvoerder voert afwijkende afspraken in de regel uit als ze tijdig en volledig worden gemeld. Daarvoor gebruikt de uitvoerder een eigen formulier en kan hij om het convenant vragen. Afspraken die niet in het systeem van de uitvoerder passen, moeten de ex-partners onderling nakomen. Controleer vooraf bij de uitvoerder wat uitvoerbaar is.`,tags:['scheiding','convenant','uitvoerder'],bron:'Wet pensioenverdeling bij scheiding'},
 {id:'pnx-130',thema:'pensioen',vraag:'Hoe beïnvloedt partneralimentatie de pensioenanalyse?',antwoord:`Partneralimentatie verandert het besteedbare inkomen van beide ex-partners. De alimentatie kan eindigen voor of na de pensioendatum. Neem de looptijd en de hoogte mee in de inkomensplanning. Bij een hypotheekaanvraag gelden eigen regels voor alimentatie.`,tags:['scheiding','alimentatie','inkomensplanning'],bron:''},
 {id:'pnx-131',thema:'pensioen',vraag:'Wanneer kan conversie van pensioen niet?',antwoord:`Conversie is niet in alle situaties mogelijk of toegestaan. Bijvoorbeeld bij pensioenen van buitenlandse uitvoerders of bijzondere constructies. Partners kunnen ook zelf een andere afspraak maken. Vraag de uitvoerder of conversie mogelijk is.`,tags:['scheiding','conversie','uitzondering'],bron:'Wet pensioenverdeling bij scheiding'},
 {id:'pnx-132',thema:'pensioen',vraag:'Hoe bewaak ik de termijn voor het melden van de scheiding?',antwoord:`Noteer de datum van inschrijving van de scheiding in het dossier. Wijs de klant op de meldtermijn en het meldformulier. Vraag later na of de melding is gedaan en of de uitvoerder heeft bevestigd. Leg die bevestiging vast.`,tags:['scheiding','termijn','dossier'],bron:'Wet pensioenverdeling bij scheiding'},
 {id:'pnx-133',thema:'pensioen',vraag:'Wat moet ik vastleggen bij pensioen en scheiding?',antwoord:`Leg minimaal vast:
- de datum van huwelijk en scheiding;
- het systeem van verdeling dat geldt;
- de afspraken uit het convenant;
- de bevestiging van de uitvoerder.
Zo kan later worden nagegaan waarop je advies rustte.`,tags:['scheiding','dossier','vastlegging'],bron:''},
 {id:'pnx-134',thema:'pensioen',vraag:'Hoe ga ik om met een klant die tijdens de scheiding pensioenadvies wil?',antwoord:`Bedenk eerst voor wie je optreedt: een van beide partners of beiden. Bij tegengestelde belangen moet je dat helder maken. Een advies aan een partner kan de andere benadelen. Leg je rol en de reikwijdte van het advies vast.`,tags:['scheiding','rol','belangenconflict'],bron:'Wft'},
 {id:'pnx-135',thema:'pensioen',vraag:'Heeft een ex-partner recht op het wezenpensioen voor de kinderen?',antwoord:`Het wezenpensioen is een recht van de kinderen, niet van de ex-partner. Het wordt uitgekeerd aan of ten behoeve van de kinderen. De scheiding verandert het recht van de kinderen in de regel niet. Controleer de regels van de uitvoerder over de uitbetaling.`,tags:['scheiding','wezenpensioen','kinderen'],bron:'Pensioenwet'},
 {id:'pnx-136',thema:'pensioen',vraag:'Loopt het partnerpensioen door tijdens onbetaald verlof?',antwoord:`Bij onbetaald verlof kan de pensioenopbouw stoppen of tijdelijk worden voortgezet. Ook de risicodekking voor het partnerpensioen kan per regeling anders zijn. Soms loopt de dekking alleen door als de deelnemer premie blijft betalen. Controleer het reglement voordat de klant met verlof gaat.`,tags:['nabestaanden','onbetaald verlof','partnerpensioen'],bron:'Pensioenwet'},
 {id:'pnx-137',thema:'pensioen',vraag:'Valt nabestaandenpensioen in de nalatenschap?',antwoord:`Nee, het nabestaandenpensioen is een eigen recht van de nabestaande. Het valt niet in de nalatenschap van de overledene. Het telt dus niet mee bij de verdeling tussen erfgenamen. Wel is het inkomen belast in box 1 bij de ontvanger.`,tags:['nabestaanden','nalatenschap','box 1'],bron:'Pensioenwet'},
 {id:'pnx-138',thema:'pensioen',vraag:'Wordt nabestaandenpensioen verrekend met een Anw-uitkering?',antwoord:`Nee, nabestaandenpensioen wordt in de regel niet verrekend met de Anw-uitkering. Inkomen uit arbeid en sommige uitkeringen worden wel verrekend. Daardoor is nabestaandenpensioen vaak een belangrijke aanvulling. Controleer de actuele regels van de SVB.`,tags:['nabestaanden','anw','verrekening'],bron:'SVB'},
 {id:'pnx-139',thema:'pensioen',vraag:'Wanneer eindigt een Anw-uitkering bij een nieuwe partner?',antwoord:`Een Anw-uitkering stopt bij hertrouwen of samenwonen. Ook bij het bereiken van de AOW-leeftijd stopt de uitkering. Een nabestaandenpensioen van de werkgever kan andere regels hebben. Controleer per regeling wat er gebeurt bij een nieuwe partner.`,tags:['nabestaanden','anw','nieuwe partner'],bron:'Algemene nabestaandenwet'},
 {id:'pnx-140',thema:'pensioen',vraag:'Wat is het verschil tussen partnerpensioen voor en na de pensioendatum?',antwoord:`Voor de pensioendatum is het partnerpensioen vaak op risicobasis tijdens het dienstverband. Na de pensioendatum gaat het om het partnerpensioen dat is opgebouwd of bij de ingang is vastgelegd. Een klant kan na pensionering minder dekking hebben dan ervoor. Controleer beide fases in de nabestaandenanalyse.`,tags:['nabestaanden','partnerpensioen','pensioendatum'],bron:'Pensioenwet'},
 {id:'pnx-141',thema:'pensioen',vraag:'Hoe reken ik een nabestaandentekort uit zonder actuele bedragen?',antwoord:`Zet het gewenste netto inkomen voor de nabestaande tegenover de verwachte inkomsten. Denk aan nabestaandenpensioen, Anw, eigen inkomen en uitkeringen uit verzekeringen. Het verschil is het tekort per jaar. Bereken het tekort per periode, bijvoorbeeld tot de AOW-leeftijd en daarna.`,tags:['nabestaanden','tekort','rekenvoorbeeld'],bron:''},
 {id:'pnx-142',thema:'pensioen',vraag:'Wat gebeurt er met het partnerpensioen bij ontslag of werkloosheid?',antwoord:`Bij risicobasis vervalt de dekking vaak na uitdiensttreding of na een korte uitloopperiode. Voor WW-gerechtigden kan een voortzetting gelden. Daardoor kan er tijdelijk geen of minder dekking zijn. Bespreek dit bij een baanwissel en controleer het reglement.`,tags:['nabestaanden','partnerpensioen','werkloosheid'],bron:'Pensioenwet'},
 {id:'pnx-143',thema:'pensioen',vraag:'Hoe kan een klant het partnerpensioen op risicobasis voortzetten na uitdiensttreding?',antwoord:`Sommige uitvoerders bieden een vrijwillige voortzetting van het risico tegen premie. Ook kan een ORV het gat opvangen. Vergelijk de kosten en de dekking. Controleer de voorwaarden en termijnen bij de uitvoerder of verzekeraar.`,tags:['nabestaanden','risicobasis','voortzetting'],bron:'Pensioenwet'},
 {id:'pnx-144',thema:'pensioen',vraag:'Hoe neem ik studerende kinderen mee in de nabestaandenanalyse?',antwoord:`De kosten van kinderen lopen vaak door tot na het achttiende jaar. Een wezenpensioen kan bij studie langer doorlopen, afhankelijk van de regeling. De Anw-uitkering voor de verzorgende ouder is daarentegen gekoppeld aan de leeftijd van het jongste kind. Breng de periode na het achttiende jaar apart in beeld.`,tags:['nabestaanden','kinderen','studie'],bron:'Algemene nabestaandenwet'},
 {id:'pnx-145',thema:'pensioen',vraag:'Hoe weeg ik nabestaandenpensioen af tegen een ORV bij hypotheekadvies?',antwoord:`Nabestaandenpensioen geeft een periodiek inkomen, een ORV een eenmalig bedrag. Een ORV kan de hypotheek direct verlagen. Nabestaandenpensioen helpt bij doorlopende lasten. Kijk naar de looptijd en de zekerheid van beide en leg de afweging vast in het dossier.`,tags:['nabestaanden','orv','hypotheek'],bron:''},
 {id:'pnx-146',thema:'pensioen',vraag:'Wanneer is een nabestaande alsnog verzekerd voor de Anw na een eerder huwelijk?',antwoord:`Het recht op Anw hangt af van de situatie op het moment van overlijden. Een ex-partner heeft in de regel geen recht op Anw. Er gelden specifieke voorwaarden, zoals de zorg voor een jong kind of arbeidsongeschiktheid. Verwijs naar de SVB voor een individuele beoordeling.`,tags:['nabestaanden','anw','ex-partner'],bron:'Algemene nabestaandenwet'},
 {id:'pnx-147',thema:'pensioen',vraag:'Hoe beïnvloedt het overlijden van een zzp-er de nabestaanden?',antwoord:`Een zzp-er heeft vaak geen nabestaandenpensioen via een werkgever. De nabestaanden zijn dan afhankelijk van Anw, vermogen en eigen verzekeringen. Een ORV of nabestaandenlijfrente kan een rol spelen. Bespreek dit risico expliciet met de klant.`,tags:['nabestaanden','zzp','orv'],bron:''},
 {id:'pnx-148',thema:'pensioen',vraag:'Welke fout zie je vaak bij het opvoeren van partnerpensioen in een nabestaandenanalyse?',antwoord:`Adviseurs tellen soms het te bereiken partnerpensioen op, terwijl alleen het risicodeel geldt zolang de klant in dienst is. Ook bijzonder partnerpensioen voor een ex wordt vaak vergeten. Daardoor lijkt de nabestaande beter verzorgd dan in werkelijkheid. Controleer per regeling wat er bij overlijden vandaag wordt uitgekeerd.`,tags:['nabestaanden','partnerpensioen','fouten'],bron:''},
 {id:'pnx-149',thema:'pensioen',vraag:'Hoe vaak moet ik de nabestaandensituatie van een klant herzien?',antwoord:`Herzie de situatie bij elke belangrijke gebeurtenis. Denk aan samenwonen, trouwen, kinderen, scheiding, baanwissel of een nieuwe hypotheek. Ook een overstap naar een nieuwe pensioenregeling kan de dekking veranderen. Leg in het dossier vast wanneer de laatste beoordeling plaatsvond.`,tags:['nabestaanden','herziening','levensgebeurtenis'],bron:''},
 {id:'pnx-150',thema:'pensioen',vraag:'Moet de nabestaande zelf het partnerpensioen aanvragen?',antwoord:`In veel gevallen moet het overlijden aan de uitvoerder worden gemeld. Soms gebeurt dat automatisch via de basisregistratie, maar niet altijd. Bij ongehuwd samenwonenden zijn vaak extra stukken nodig, zoals het samenlevingscontract. Help de nabestaande met een lijst van uitvoerders en benodigde documenten.`,tags:['nabestaanden','partnerpensioen','aanvraag'],bron:'Pensioenwet'},
 {id:'pnx-151',thema:'pensioen',vraag:'Hoe verandert het nabestaandeninkomen als de partner de AOW-leeftijd bereikt?',antwoord:`De Anw-uitkering stopt bij de AOW-leeftijd van de nabestaande. Daarvoor in de plaats komt de AOW voor alleenstaanden, tenzij er een nieuwe partner is. Een tijdelijk nabestaandenpensioen kan op hetzelfde moment eindigen. Breng deze overgang apart in beeld.`,tags:['nabestaanden','aow','anw'],bron:'SVB'},
 {id:'pnx-152',thema:'pensioen',vraag:'Wat is een tijdelijk partnerpensioen?',antwoord:`Sommige regelingen kennen naast een levenslang partnerpensioen een tijdelijke uitkering. Die loopt bijvoorbeeld tot de AOW-leeftijd van de nabestaande. Het doel is vaak het opvangen van het verschil tot de AOW. Controleer de looptijd en de voorwaarden in het reglement.`,tags:['nabestaanden','tijdelijk partnerpensioen'],bron:'Pensioenwet'},
 {id:'pnx-153',thema:'pensioen',vraag:'Hoe ga ik om met nabestaandenpensioen bij een groot leeftijdsverschil?',antwoord:`Sommige regelingen korten het partnerpensioen bij een groot leeftijdsverschil. Ook bij een huwelijk na de pensioendatum kan de dekking beperkt zijn. Lees het reglement daarop na. Bespreek het risico met beide partners en leg de bevindingen vast.`,tags:['nabestaanden','leeftijdsverschil','reglement'],bron:'Pensioenwet'},
 {id:'pnx-154',thema:'pensioen',vraag:'Heeft een partner van een gepensioneerde altijd recht op partnerpensioen?',antwoord:`Niet altijd. Als de relatie na de pensioendatum is ontstaan, is er soms geen partnerpensioen verzekerd. Ook kan het partnerpensioen bij pensioeningang zijn uitgeruild. Controleer dit bij de uitvoerder voordat je ervan uitgaat in een analyse.`,tags:['nabestaanden','gepensioneerde','partnerpensioen'],bron:'Pensioenwet'},
 {id:'pnx-155',thema:'pensioen',vraag:'Hoe leg ik een nabestaandenanalyse goed vast?',antwoord:`Noteer per scenario welke inkomsten de nabestaande krijgt en welke lasten doorlopen. Vermeld de bronnen, zoals overzichten en polissen. Beschrijf het tekort en de besproken oplossingen. Leg ook vast welke keuze de klant maakt en waarom.`,tags:['nabestaanden','dossier','vastlegging'],bron:'Wft'},
 {id:'pnx-156',thema:'pensioen',vraag:'Welke kosten van een nabestaande worden vaak vergeten?',antwoord:`Denk aan kosten van uitvaart, kinderopvang en extra hulp in huis. Ook vervalt soms een korting of toeslag. Het netto inkomen kan anders uitvallen door een andere belastingpositie. Neem deze posten mee in de berekening van het tekort.`,tags:['nabestaanden','kosten','tekort'],bron:''},
 {id:'pnx-157',thema:'pensioen',vraag:'Kan een nabestaande het partnerpensioen afkopen?',antwoord:`Een klein partnerpensioen kan onder voorwaarden worden afgekocht. Bij grotere bedragen is afkoop meestal niet mogelijk. De afkoopgrens wordt jaarlijks vastgesteld. Controleer het actuele bedrag en de regels bij de uitvoerder.`,tags:['nabestaanden','afkoop','klein pensioen'],bron:'Pensioenwet'},
 {id:'pnx-158',thema:'pensioen',vraag:'Wat is het verschil tussen nabestaandenpensioen en een nabestaandenlijfrente?',antwoord:`Nabestaandenpensioen komt voort uit een werkgeversregeling. Een nabestaandenlijfrente is een individueel product waarmee een nabestaande een periodieke uitkering krijgt. De fiscale behandeling verschilt. Controleer de voorwaarden van het product en de fiscale regels.`,tags:['nabestaanden','lijfrente','verschil'],bron:'Wet IB 2001'},
 {id:'pnx-159',thema:'pensioen',vraag:'Hoe bereken ik de jaarruimte zonder actuele percentages?',antwoord:`De jaarruimte gaat uit van de premiegrondslag van het voorgaande jaar. Daarop worden de pensioenopbouw (factor A) en eventuele andere correcties in mindering gebracht. De percentages en grenzen veranderen per jaar. Gebruik de rekenhulp van de Belastingdienst met de actuele gegevens.`,tags:['jaarruimte','berekening','factor a'],bron:'Belastingdienst'},
 {id:'pnx-160',thema:'pensioen',vraag:'Waar vindt de klant de factor A?',antwoord:`De factor A staat op het UPO of in een aparte opgave van de pensioenuitvoerder. Het gaat om de pensioenaangroei in het voorgaande jaar. Bij meerdere werkgevers moeten alle factoren A worden opgeteld. Vraag om alle opgaven voordat je de jaarruimte berekent.`,tags:['jaarruimte','factor a','upo'],bron:'Belastingdienst'},
 {id:'pnx-161',thema:'pensioen',vraag:'Hoeveel jaren terug telt de reserveringsruimte?',antwoord:`De reserveringsruimte gaat over niet-benutte jaarruimte uit een aantal voorgaande jaren. Sinds de wetswijziging gaat het om maximaal tien jaren. De ruimte van het oudste jaar wordt het eerst gebruikt. Controleer de actuele regels en het maximum per jaar bij de Belastingdienst.`,tags:['reserveringsruimte','jaren','lijfrente'],bron:'Belastingdienst'},
 {id:'pnx-162',thema:'pensioen',vraag:'Wanneer is premie voor lijfrente aftrekbaar?',antwoord:`Premie is in principe aftrekbaar in het jaar van betaling. Dat geldt alleen als de klant jaarruimte of reserveringsruimte heeft. Het product moet voldoen aan de fiscale eisen. Bewaar de betaalbewijzen en de berekening van de ruimte in het dossier.`,tags:['lijfrente','aftrek','jaarruimte'],bron:'Wet IB 2001'},
 {id:'pnx-163',thema:'pensioen',vraag:'Wat is het verschil tussen een bancaire lijfrente en een lijfrenteverzekering?',antwoord:`Bij een bancaire lijfrente gaat het om een geblokkeerde spaar- of beleggingsrekening. Bij een lijfrenteverzekering sluit de klant een verzekering bij een verzekeraar. Bij overlijden en in de uitkeringsfase kunnen de mogelijkheden verschillen. Vergelijk de voorwaarden en kosten van beide.`,tags:['lijfrente','bancair','verzekering'],bron:'Wet IB 2001'},
 {id:'pnx-164',thema:'pensioen',vraag:'Valt een lijfrenteaanspraak in box 3?',antwoord:`Nee, een fiscaal gefaciliteerde lijfrente valt niet in box 3. De premie is aftrekbaar en de uitkering is belast in box 1. Dit heet de omkeerregel. Daardoor kan het netto voordeel groot zijn bij een lager tarief na pensionering.`,tags:['lijfrente','box 3','omkeerregel'],bron:'Wet IB 2001'},
 {id:'pnx-165',thema:'pensioen',vraag:'Wat is een niet-toegestane handeling bij lijfrente?',antwoord:`Een niet-toegestane handeling is bijvoorbeeld afkopen, vervreemden of belenen buiten de fiscale regels. De volledige waarde wordt dan belast in box 1. Daarnaast kan revisierente verschuldigd zijn. Leg de klant uit dat een lijfrente geblokkeerd vermogen is.`,tags:['lijfrente','afkoop','revisierente'],bron:'Wet IB 2001'},
 {id:'pnx-166',thema:'pensioen',vraag:'Mag een lijfrente worden verpand aan een geldverstrekker?',antwoord:`Verpanden of belenen van een lijfrente is in de regel een niet-toegestane handeling. Dat kan leiden tot belastingheffing over de hele waarde en revisierente. Gebruik lijfrente dus niet als zekerheid voor een hypotheek. Controleer bij twijfel de fiscale regels.`,tags:['lijfrente','verpanding','hypotheek'],bron:'Wet IB 2001'},
 {id:'pnx-167',thema:'pensioen',vraag:'Wanneer moet een oudedagslijfrente ingaan?',antwoord:`Een oudedagslijfrente moet binnen fiscale termijnen ingaan, rond de AOW-leeftijd. Er zijn grenzen aan hoe vroeg en hoe laat dat kan. Deze grenzen kunnen wijzigen. Controleer de actuele regels voordat je de klant adviseert.`,tags:['lijfrente','ingangsdatum','aow'],bron:'Wet IB 2001'},
 {id:'pnx-168',thema:'pensioen',vraag:'Wat is een tijdelijke oudedagslijfrente?',antwoord:`Een tijdelijke oudedagslijfrente keert een vast aantal jaren uit in plaats van levenslang. Er gelden fiscale minimumlooptijden, afhankelijk van de ingangsdatum. Een tijdelijke uitkering kan het AOW-gat overbruggen of een hogere uitkering geven. Laat zien wat er na afloop van de looptijd overblijft.`,tags:['lijfrente','tijdelijk','looptijd'],bron:'Wet IB 2001'},
 {id:'pnx-169',thema:'pensioen',vraag:'Hoe kies ik tussen een levenslange en een tijdelijke lijfrente-uitkering?',antwoord:`Een levenslange uitkering beschermt tegen langlevenrisico. Een tijdelijke uitkering is hoger per jaar maar stopt na de looptijd. De keuze hangt af van andere inkomsten en de wensen van de klant. Leg de afweging en de gevolgen vast in het dossier.`,tags:['lijfrente','levenslang','tijdelijk'],bron:''},
 {id:'pnx-170',thema:'pensioen',vraag:'Wat gebeurt er met een lijfrente bij overlijden in de opbouwfase?',antwoord:`Het opgebouwde kapitaal kan overgaan naar de nabestaanden of erfgenamen. Er gelden regels voor wie het kan voortzetten als lijfrente. Bij afkoop door erfgenamen gelden aparte fiscale regels. Controleer de begunstiging en de voorwaarden van het product.`,tags:['lijfrente','overlijden','erfgenamen'],bron:'Wet IB 2001'},
 {id:'pnx-171',thema:'pensioen',vraag:'Kan een klant zijn lijfrente overdragen naar een andere aanbieder?',antwoord:`Ja, overdracht naar een andere aanbieder is mogelijk zonder belastingheffing. Er gelden wel voorwaarden, bijvoorbeeld voor rechtstreekse overdracht. De aanbieder kan kosten rekenen. Vergelijk de voorwaarden en kosten en leg de motivering vast.`,tags:['lijfrente','overdracht','aanbieder'],bron:'Wet IB 2001'},
 {id:'pnx-172',thema:'pensioen',vraag:'Waarom moet ik bij lijfrente-advies het verwachte belastingtarief na pensioen meenemen?',antwoord:`Het voordeel van lijfrente zit vaak in het verschil tussen het tarief bij aftrek en bij uitkering. Is het tarief later even hoog, dan is het voordeel kleiner. Ook de heffingskortingen en toeslagen spelen mee. Maak een indicatieve berekening en benoem de onzekerheid.`,tags:['lijfrente','belastingtarief','afweging'],bron:'Belastingdienst'},
 {id:'pnx-173',thema:'pensioen',vraag:'Mag een klant met jaarruimte ook voor de partner inleggen?',antwoord:`Jaarruimte is persoonlijk en geldt alleen voor de klant zelf. Elke partner moet zijn eigen ruimte berekenen. Inleg op naam van de andere partner levert geen aftrek op voor de inlegger. Bereken de ruimte dus voor beide partners afzonderlijk.`,tags:['jaarruimte','partner','persoonlijk'],bron:'Belastingdienst'},
 {id:'pnx-174',thema:'pensioen',vraag:'Hoe zit het met jaarruimte voor een ondernemer?',antwoord:`Voor een ondernemer telt de winst als basis voor de premiegrondslag. Een ondernemer heeft vaak geen werkgeverspensioen en dus meer ruimte. De berekening hangt af van de actuele percentages en grenzen. Gebruik de rekenhulp van de Belastingdienst.`,tags:['jaarruimte','ondernemer','winst'],bron:'Belastingdienst'},
 {id:'pnx-175',thema:'pensioen',vraag:'Hoe stem ik de ingangsdatum van een lijfrente af op het werkgeverspensioen?',antwoord:`Breng eerst in beeld wanneer het werkgeverspensioen en de AOW ingaan. Een lijfrente kan een periode met laag inkomen opvullen of het inkomen later aanvullen. Een slimme timing kan de belastingdruk over de jaren spreiden. Blijf binnen de fiscale termijnen en leg de gekozen opzet vast.`,tags:['lijfrente','ingangsdatum','timing'],bron:'Wet IB 2001'},
 {id:'pnx-176',thema:'pensioen',vraag:'Wat is een stakingslijfrente?',antwoord:`Bij staking van een onderneming kan een ondernemer een deel van de stakingswinst omzetten in een lijfrente. Daarvoor geldt een aparte aftrekruimte. De bedragen hangen af van leeftijd en actuele grenzen. Laat een fiscalist de berekening controleren.`,tags:['lijfrente','stakingswinst','ondernemer'],bron:'Wet IB 2001'},
 {id:'pnx-177',thema:'pensioen',vraag:'Wat is een lijfrente voor een meerderjarig invalide kind?',antwoord:`De wet kent een fiscale faciliteit voor een lijfrente ten behoeve van een invalide (klein)kind. Ouders kunnen zo een uitkering voor het kind regelen. Er gelden voorwaarden aan de mate van invaliditeit en de premie. Laat een fiscalist de voorwaarden controleren.`,tags:['lijfrente','invalide kind','faciliteit'],bron:'Wet IB 2001'},
 {id:'pnx-178',thema:'pensioen',vraag:'Mag een klant lijfrente opnemen bij arbeidsongeschiktheid?',antwoord:`Er bestaat een uitzondering voor opname bij ernstige arbeidsongeschiktheid. Dan kan de klant onder voorwaarden opnemen zonder revisierente. De opname is wel belast in box 1. Controleer de actuele voorwaarden en leg ze vast.`,tags:['lijfrente','arbeidsongeschiktheid','opname'],bron:'Wet IB 2001'},
 {id:'pnx-179',thema:'pensioen',vraag:'Hoe beïnvloedt lijfrente-inleg de toeslagen?',antwoord:`Lijfrentepremie verlaagt het verzamelinkomen. Daardoor kunnen toeslagen hoger uitvallen. Dat is een extra voordeel naast de belastingbesparing. Bereken het effect met de actuele gegevens van de Belastingdienst.`,tags:['lijfrente','toeslagen','verzamelinkomen'],bron:'Belastingdienst'},
 {id:'pnx-180',thema:'pensioen',vraag:'Welke fout maken adviseurs vaak bij jaarruimte?',antwoord:`Een veelgemaakte fout is het rekenen met het verkeerde jaar of een onvolledige factor A. Ook wordt soms vergeten dat de jaarruimte jaarlijks wijzigt. Daardoor wordt meer ingelegd dan aftrekbaar is. Controleer de berekening met de rekenhulp en bewaar die in het dossier.`,tags:['jaarruimte','fouten','factor a'],bron:'Belastingdienst'},
 {id:'pnx-181',thema:'pensioen',vraag:'Wat gebeurt er als een klant meer inlegt dan de jaarruimte?',antwoord:`Het deel boven de jaarruimte en reserveringsruimte is niet aftrekbaar. Hoe dat deel bij uitkering fiscaal wordt behandeld, vraagt aandacht. Laat de klant de bewijzen van inleg bewaren en schakel bij twijfel een fiscalist in. Voorkom dit door de ruimte vooraf goed te berekenen.`,tags:['jaarruimte','overschrijding','administratie'],bron:'Belastingdienst'},
 {id:'pnx-182',thema:'pensioen',vraag:'Hoe laat ik de klant de reserveringsruimte gebruiken?',antwoord:`Bereken eerst de jaarruimte van het lopende jaar. Daarna kan de klant niet-benutte ruimte uit eerdere jaren gebruiken. Het oudste jaar komt eerst aan de beurt. Bewaar het overzicht van eerder gebruikte ruimte bij de berekening.`,tags:['reserveringsruimte','gebruik','berekening'],bron:'Belastingdienst'},
 {id:'pnx-183',thema:'pensioen',vraag:'Hoe adviseer ik een klant met een pensioentekort die geen jaarruimte heeft?',antwoord:`Zonder jaarruimte of reserveringsruimte is lijfrente-inleg niet aftrekbaar. De klant kan dan sparen of beleggen in box 3. Ook extra aflossen op de hypotheek kan het pensioengat verkleinen. Leg de afweging tussen deze opties vast.`,tags:['lijfrente','pensioentekort','alternatieven'],bron:''},
 {id:'pnx-184',thema:'pensioen',vraag:'Wat is het risico van een lijfrente met een korte looptijd tot de pensioendatum?',antwoord:`Bij een korte looptijd is er minder tijd om beleggingsverliezen in te halen. Een daling vlak voor de uitkering kan grote gevolgen hebben. Kies daarom een risicoprofiel dat past bij de horizon. Leg de keuze en de risicobereidheid vast.`,tags:['lijfrente','looptijd','risico'],bron:''},
 {id:'pnx-185',thema:'pensioen',vraag:'Mag een klant zijn lijfrente-uitkering uitstellen?',antwoord:`De ingangsdatum van een lijfrente mag binnen de fiscale grenzen worden gekozen. Uitstel kan voordelig zijn als de klant nog ander inkomen heeft. Na het verstrijken van de uiterste termijn kan belastingheffing volgen. Controleer de termijnen in het product en de wet.`,tags:['lijfrente','uitstel','termijn'],bron:'Wet IB 2001'},
 {id:'pnx-186',thema:'pensioen',vraag:'Wanneer ziet een klant een nieuwe baan met pensioenopbouw terug in zijn jaarruimte?',antwoord:`De jaarruimte wordt berekend met de premiegrondslag en de factor A van het voorgaande jaar. Een baanwissel in het lopende jaar werkt dus pas het jaar erna door. Wie een pensioenregeling krijgt, heeft daarna vaak minder jaarruimte. Bespreek dit met een klant die bij een baanwissel nog wil inleggen.`,tags:['jaarruimte','baanwissel','factor a'],bron:'Belastingdienst'},
 {id:'pnx-187',thema:'pensioen',vraag:'Wat moet ik vastleggen bij een lijfrente-advies?',antwoord:`Leg minimaal vast:
- de berekening van jaarruimte en reserveringsruimte;
- het doel en de looptijd;
- het gekozen product en profiel;
- de risicobereidheid en de kosten.
Bewaar de bronnen bij het advies.`,tags:['lijfrente','dossier','vastlegging'],bron:'Wft'},
 {id:'pnx-188',thema:'pensioen',vraag:'Kan een klant na emigratie zijn lijfrente behouden?',antwoord:`Een lijfrente kan bij emigratie blijven bestaan. Er kan wel een conserverende aanslag worden opgelegd. Ook de belasting op de uitkering hangt af van verdragen. Verwijs naar een fiscalist met kennis van internationale situaties.`,tags:['lijfrente','emigratie','conserverende aanslag'],bron:'Belastingdienst'},
 {id:'pnx-189',thema:'pensioen',vraag:'Wat is het verschil tussen een lijfrentespaarrekening en een lijfrentebeleggingsrecht?',antwoord:`Bij een spaarrekening ontvangt de klant rente zonder koersrisico. Bij een beleggingsrecht belegt de klant met kans op hoger rendement en risico. De keuze hangt af van de horizon en de risicobereidheid. Wissel tussen beide is vaak mogelijk binnen dezelfde aanbieder.`,tags:['lijfrente','sparen','beleggen'],bron:'Wet IB 2001'},
 {id:'pnx-190',thema:'pensioen',vraag:'Hoe ga ik om met meerdere kleine lijfrentes?',antwoord:`Meerdere kleine lijfrentes kunnen worden samengevoegd door overdracht. Dat vereenvoudigt de administratie en kan kosten besparen. Let op voorwaarden en eventuele kosten bij overdracht. Kleine bedragen kunnen soms worden afgekocht onder de afkoopgrens.`,tags:['lijfrente','samenvoegen','afkoop'],bron:'Wet IB 2001'},
 {id:'pnx-191',thema:'pensioen',vraag:'Wat is een veelgemaakte fout bij lijfrente-uitkeringen?',antwoord:`Klanten laten soms een lijfrente niet tijdig ingaan. Ook wordt vergeten dat de uitkering belast is. Daardoor valt het netto inkomen lager uit dan verwacht. Wijs de klant op de termijnen en maak een netto-berekening.`,tags:['lijfrente','fouten','uitkering'],bron:''},
 {id:'pnx-192',thema:'pensioen',vraag:'Hoe verhoudt lijfrente zich tot het AOW-gat?',antwoord:`Een tijdelijke lijfrente kan het AOW-gat overbruggen. De looptijd moet dan aansluiten op de AOW-datum. Fiscaal gelden minimumlooptijden. Controleer of de opzet past binnen de fiscale regels.`,tags:['lijfrente','aow-gat','overbrugging'],bron:'Wet IB 2001'},
 {id:'pnx-193',thema:'pensioen',vraag:'Wat gebeurt er met een lijfrente bij een faillissement van de klant?',antwoord:`Een lijfrente valt in beginsel in de faillissementsboedel. Of en hoe de curator de waarde kan opeisen, hangt af van de situatie en de jurisprudentie. De situatie is juridisch complex. Verwijs naar een jurist of curator.`,tags:['lijfrente','faillissement','bescherming'],bron:'Faillissementswet'},
 {id:'pnx-194',thema:'pensioen',vraag:'Kan lijfrente in de uitkeringsfase nog worden belegd?',antwoord:`Bij sommige producten kan de klant ook in de uitkeringsfase blijven beleggen. De uitkering kan dan variëren. Dat geeft kans op een hogere uitkering, maar ook risico. Controleer de voorwaarden van het product en leg de keuze vast.`,tags:['lijfrente','uitkeringsfase','beleggen'],bron:''},
 {id:'pnx-195',thema:'pensioen',vraag:'Welke kosten van lijfrenteproducten moet ik met de klant bespreken?',antwoord:`Bespreek beheerkosten, fondskosten en eventuele overdrachts- of uitkeringskosten. Kleine verschillen kunnen over een lange periode groot uitpakken. Vergelijk producten op totale kosten. Leg de kostenvergelijking vast.`,tags:['lijfrente','kosten','vergelijking'],bron:'Wft'},
 {id:'pnx-196',thema:'pensioen',vraag:'Welke Wft-kennis heb ik nodig om over lijfrente te adviseren?',antwoord:`Voor advies over lijfrente moet je beschikken over de juiste Wft-vakbekwaamheid. Welke module nodig is, hangt af van het product. Houd je kennis bij via permanente educatie. Controleer de eisen voor jouw situatie bij de toezichthouder.`,tags:['lijfrente','wft','vakbekwaamheid'],bron:'AFM'},
 {id:'pnx-197',thema:'pensioen',vraag:'Wat moet ik doen als een klant een lijfrente wil afkopen om schulden te betalen?',antwoord:`Afkoop leidt tot belasting in box 1 en mogelijk revisierente. Het netto bedrag kan daardoor veel lager zijn dan de waarde. Bekijk eerst andere oplossingen, zoals schuldhulp of een betalingsregeling. Leg de afweging en de gevolgen vast in het dossier.`,tags:['lijfrente','afkoop','schulden'],bron:'Wet IB 2001'},
 {id:'pnx-198',thema:'pensioen',vraag:'Hoe ga ik om met een oude lijfrentepolis met een verlopen ingangsdatum?',antwoord:`Als de ingangsdatum is verstreken zonder uitkering, kan dat fiscale gevolgen hebben. Neem snel contact op met de aanbieder. Soms is herstel mogelijk binnen een termijn. Verwijs bij twijfel naar een fiscalist.`,tags:['lijfrente','ingangsdatum','herstel'],bron:'Wet IB 2001'},
 {id:'pnx-199',thema:'pensioen',vraag:'Kan een klant een lijfrente inbrengen in een hypotheekoplossing?',antwoord:`Een lijfrente kan niet als onderpand dienen. Wel kan de uitkering later helpen bij de betaalbaarheid van de woonlasten. Een geldverstrekker beoordeelt dat volgens eigen regels. Controleer de acceptatievoorwaarden en leg de afweging vast.`,tags:['lijfrente','hypotheek','betaalbaarheid'],bron:''},
 {id:'pnx-200',thema:'pensioen',vraag:'Telt een lijfrente-uitkering mee voor de inkomensafhankelijke zorgkosten en toeslagen?',antwoord:`Een lijfrente-uitkering is belast inkomen in box 1. Daardoor telt het mee voor het verzamelinkomen en dus voor toeslagen en inkomensafhankelijke regelingen. Een hogere uitkering kan zo leiden tot lagere toeslagen. Neem dit mee in de keuze tussen een hoge korte of een lage lange uitkering.`,tags:['lijfrente','uitkering','toeslagen'],bron:'Belastingdienst'},
 {id:'pnx-201',thema:'pensioen',vraag:'Hoe zie ik of de pensioenbrief van een DGA niet meer klopt?',antwoord:`Kijk naar de datum en of de brief past bij de keuze die bij de uitfasering is gemaakt. Let op partnerdefinities, ingangsdatum en verwijzingen naar oude regels. Een verouderde brief kan tot discussie leiden bij scheiding, overlijden of verkoop. Leg je bevindingen vast en verwijs voor aanpassing naar een fiscalist of jurist.`,tags:['dga','pensioenbrief','actualiteit'],bron:'Wet uitfasering pensioen in eigen beheer'},
 {id:'pnx-202',thema:'pensioen',vraag:'Waarom moest de partner van de DGA instemmen met keuzes bij de uitfasering?',antwoord:`Keuzes als afkoop of omzetting raakten ook het partnerpensioen. Daarom was schriftelijke instemming van de partner vereist. Ontbreekt die, dan kan de keuze aanvechtbaar zijn. Controleer bij een DGA-dossier of de instemming aanwezig is.`,tags:['dga','partner','instemming'],bron:'Wet uitfasering pensioen in eigen beheer'},
 {id:'pnx-203',thema:'pensioen',vraag:'Wat is het verschil tussen de fiscale en de commerciële waarde van een eigenbeheerpensioen?',antwoord:`De fiscale waarde wordt berekend met fiscale rekenregels. De commerciële waarde gaat uit van marktrente en actuele sterftetafels. De commerciële waarde is vaak hoger. Het verschil is van belang voor de jaarrekening en een eventuele overdracht.`,tags:['dga','eigen beheer','waardering'],bron:'Wet uitfasering pensioen in eigen beheer'},
 {id:'pnx-204',thema:'pensioen',vraag:'Wat gebeurt er met de pensioenverplichting als de DGA zijn BV verkoopt?',antwoord:`Een koper wil meestal geen pensioenverplichting overnemen. De verplichting kan dan worden overgedragen aan een verzekeraar of een eigen pensioen-BV. Dat vraagt vaak extra middelen. Betrek een fiscalist en leg de afweging vast.`,tags:['dga','verkoop bv','pensioenverplichting'],bron:'Wet IB 2001'},
 {id:'pnx-205',thema:'pensioen',vraag:'Hoe beïnvloedt een pensioenverplichting de dividenduitkering van de BV?',antwoord:`Het bestuur moet bij een uitkering beoordelen of de BV haar verplichtingen kan blijven nakomen. Een pensioenverplichting weegt daarbij mee. Een te ruime uitkering kan aansprakelijkheid opleveren. Controleer de jaarrekening en de uitkeringstoets.`,tags:['dga','dividend','uitkeringstoets'],bron:'Burgerlijk Wetboek'},
 {id:'pnx-206',thema:'pensioen',vraag:'Kan een DGA die stopt met werken direct pensioen uit de BV ontvangen?',antwoord:`Dat hangt af van de ingangsdatum in de pensioenbrief of de ODV. Eerder laten ingaan heeft gevolgen voor de hoogte. Ook gelden fiscale grenzen. Controleer de documenten en laat een fiscalist rekenen.`,tags:['dga','ingangsdatum','eigen beheer'],bron:'Wet IB 2001'},
 {id:'pnx-207',thema:'pensioen',vraag:'Is het hele salaris van een DGA pensioengevend in een externe regeling?',antwoord:`Nee, het pensioengevend salaris is fiscaal begrensd. Boven dat maximum mag geen fiscaal gefaciliteerd pensioen worden opgebouwd. Het actuele maximum verandert jaarlijks, zie de Belastingdienst. Voor het meerdere kan de DGA andere vormen van vermogensopbouw overwegen.`,tags:['dga','pensioengevend salaris','maximum'],bron:'Belastingdienst'},
 {id:'pnx-208',thema:'pensioen',vraag:'Hoe beïnvloedt het gebruikelijk loon de jaarruimte van een DGA?',antwoord:`De jaarruimte van een DGA in loondienst hangt af van zijn salaris. Een laag salaris geeft weinig jaarruimte. Het gebruikelijk loon kent eigen regels en bedragen. Controleer het actuele loon en reken de jaarruimte na.`,tags:['dga','gebruikelijk loon','jaarruimte'],bron:'Belastingdienst'},
 {id:'pnx-209',thema:'pensioen',vraag:'Wat is een veelgemaakte fout bij een DGA met een ODV?',antwoord:`Adviseurs gaan soms uit van een levenslange uitkering, terwijl de ODV andere regels kan hebben. Ook wordt de solvabiliteit van de BV vaak niet bekeken. Een ODV is zo zeker als de BV die moet betalen. Controleer de akte en de financiële positie van de BV.`,tags:['dga','odv','fouten'],bron:'Wet uitfasering pensioen in eigen beheer'},
 {id:'pnx-210',thema:'pensioen',vraag:'Kan een ODV worden overgedragen naar een verzekeraar of bank?',antwoord:`Een ODV kan onder voorwaarden worden ondergebracht bij een verzekeraar of bank. Dat haalt het risico uit de BV. Er gelden fiscale regels voor deze overdracht. Laat een fiscalist de voorwaarden controleren.`,tags:['dga','odv','overdracht'],bron:'Wet IB 2001'},
 {id:'pnx-211',thema:'pensioen',vraag:'Hoe beoordeel ik de zekerheid van een eigenbeheerpensioen?',antwoord:`Kijk naar de balans, de liquiditeit en de toekomstplannen van de BV. Een pensioen in eigen beheer is niet afgezonderd zoals bij een verzekeraar. Als de BV niet kan betalen, ontstaat een tekort. Leg de beoordeling vast in het dossier.`,tags:['dga','eigen beheer','zekerheid'],bron:''},
 {id:'pnx-212',thema:'pensioen',vraag:'Hoe telt pensioen uit de eigen BV mee bij een hypotheekaanvraag?',antwoord:`Geldverstrekkers kijken bij pensioen uit eigen beheer vaak naar de financiële positie van de BV. Soms worden aanvullende stukken gevraagd, zoals jaarrekeningen. De beoordeling verschilt per geldverstrekker. Controleer de voorwaarden van de geldverstrekker.`,tags:['dga','hypotheek','eigen beheer'],bron:'Gedragscode Hypothecaire Financieringen'},
 {id:'pnx-213',thema:'pensioen',vraag:'Wat moet ik vastleggen in een DGA-pensioendossier?',antwoord:`Leg minimaal vast:
- de pensioenbrief of ODV-akte;
- de keuze bij de uitfasering;
- de waardering in de jaarrekening;
- de beoordeling van de BV.
Zo is de grondslag van het advies te controleren.`,tags:['dga','dossier','vastlegging'],bron:''},
 {id:'pnx-214',thema:'pensioen',vraag:'Wat gebeurt er met een eigenbeheerpensioen bij overlijden van de DGA?',antwoord:`Bij een premievrij pensioen kan er een partnerpensioen voor de partner zijn. Bij een ODV kan er een uitkering aan de partner of erfgenamen gaan. De BV moet die verplichting nakomen. Controleer de documenten en de liquiditeit van de BV.`,tags:['dga','overlijden','nabestaanden'],bron:'Wet uitfasering pensioen in eigen beheer'},
 {id:'pnx-215',thema:'pensioen',vraag:'Valt een DGA onder de verplichtstelling van een bedrijfstakpensioenfonds?',antwoord:`Een DGA valt in veel gevallen niet onder de verplichtstelling. Dat hangt af van de definities in de regeling en de positie van de DGA. Soms is een vrijstelling nodig. Controleer de situatie bij het fonds.`,tags:['dga','bedrijfstakpensioenfonds','verplichtstelling'],bron:'Wet verplichte deelneming in een bedrijfstakpensioenfonds'},
 {id:'pnx-216',thema:'pensioen',vraag:'Hoe adviseer ik een DGA die zijn BV wil liquideren?',antwoord:`Bij liquidatie moet de pensioenverplichting worden afgewikkeld. Dat kan door overdracht aan een verzekeraar of op andere toegestane wijze. Fiscale fouten kunnen tot directe belasting leiden. Betrek een fiscalist voordat de liquidatie start.`,tags:['dga','liquidatie','pensioenverplichting'],bron:'Wet IB 2001'},
 {id:'pnx-217',thema:'pensioen',vraag:'Heeft een DGA recht op WW bij stoppen?',antwoord:`Een DGA met een zeggenschapspositie is vaak niet verzekerd voor werknemersverzekeringen. Daardoor is er geen WW. Het inkomen tot pensioen moet dan uit andere bronnen komen. Controleer de verzekeringsplicht bij het UWV.`,tags:['dga','ww','inkomen'],bron:'UWV'},
 {id:'pnx-218',thema:'pensioen',vraag:'Hoe vergelijk ik een externe pensioenregeling met lijfrente voor een DGA?',antwoord:`Een externe regeling loopt via de BV en kan premieaftrek in de BV geven. Lijfrente is privé en loopt via de jaarruimte. De keuze hangt af van de fiscale positie en de flexibiliteit. Leg de vergelijking vast in het dossier.`,tags:['dga','externe regeling','lijfrente'],bron:'Wet IB 2001'},
 {id:'pnx-219',thema:'pensioen',vraag:'Wat is een pensioen-BV?',antwoord:`Een pensioen-BV is een aparte BV waarin een pensioenverplichting wordt ondergebracht. Dat gebeurt vaak bij verkoop van de werk-BV. De pensioen-BV moet zelf voldoende middelen hebben. Laat een fiscalist de structuur beoordelen.`,tags:['dga','pensioen-bv','structuur'],bron:'Wet IB 2001'},
 {id:'pnx-220',thema:'pensioen',vraag:'Wat is het risico van een DGA zonder pensioenopbouw?',antwoord:`Zonder opbouw is de DGA afhankelijk van de waarde van de BV en eigen vermogen. Bij tegenvallers kan het oudedagsinkomen sterk dalen. Ook een partner kan onvoldoende verzorgd zijn. Bespreek dit risico en leg de afweging vast.`,tags:['dga','pensioentekort','risico'],bron:''},
 {id:'pnx-221',thema:'pensioen',vraag:'Waarom zijn er aparte leennormen voor AOW-gerechtigden?',antwoord:`De Nibud-leennormen kennen eigen financieringslastpercentages voor huishoudens met AOW-leeftijd. Dit komt door andere inkomens- en belastingposities. De percentages zijn afgerond op 0,1 procent. Gebruik altijd de actuele tabel bij de toets.`,tags:['hypotheek','aow','leennormen'],bron:'Nibud'},
 {id:'pnx-222',thema:'pensioen',vraag:'Geldt de aflossingseis ook voor een nieuwe hypotheek van een zestigjarige?',antwoord:`Ja, voor renteaftrek op een eigenwoningschuld vanaf 2013 geldt een aflossingseis van 360 maanden annuïtair of lineair. Die eis is niet afhankelijk van de leeftijd. De geldverstrekker kan wel extra eisen stellen. Bespreek de betaalbaarheid tot het einde van de looptijd.`,tags:['hypotheek','aflossingseis','senior'],bron:'Wet IB 2001'},
 {id:'pnx-223',thema:'pensioen',vraag:'Hoe breng ik de woonlasten per levensfase in beeld voor een klant van vijftig?',antwoord:`Maak een tijdlijn met de belangrijke momenten: nu, stoppen met werken, de AOW-leeftijd en het overlijden van een partner. Zet per periode het verwachte netto inkomen naast de woonlasten. Zo ziet de klant waar knelpunten ontstaan. Leg de uitgangspunten en de besproken maatregelen vast.`,tags:['hypotheek','levensfase','tijdlijn'],bron:''},
 {id:'pnx-224',thema:'pensioen',vraag:'Telt inkomen uit werk na de AOW-leeftijd mee voor een hypotheek?',antwoord:`Werk na de AOW-leeftijd is vaak onzeker en tijdelijk. Geldverstrekkers zijn daarom terughoudend met het meetellen van dit inkomen. Gebruik voor de lange termijn het blijvende inkomen uit AOW en pensioen. Controleer de acceptatievoorwaarden van de geldverstrekker.`,tags:['hypotheek','doorwerken','aow'],bron:'Gedragscode Hypothecaire Financieringen'},
 {id:'pnx-225',thema:'pensioen',vraag:'Hoe neem ik servicekosten van een appartement mee na pensionering?',antwoord:`Bij een appartement komen bovenop de hypotheek vaak VvE-bijdragen en soms servicekosten. Deze lasten kunnen in de loop der jaren stijgen. Met een vast pensioeninkomen is daar minder ruimte voor. Neem deze kosten op in de begroting en leg de analyse vast.`,tags:['hypotheek','vve','betaalbaarheid'],bron:''},
 {id:'pnx-226',thema:'pensioen',vraag:'Waar let ik op als een gepensioneerde zijn hypotheek wil oversluiten?',antwoord:`Bij oversluiten wordt opnieuw getoetst, nu op basis van het pensioeninkomen. Dat kan minder ruimte geven dan bij de oorspronkelijke lening. Ook een eventuele boete en de kosten tellen mee. Leg de vergelijking tussen blijven en oversluiten vast in het dossier.`,tags:['hypotheek','oversluiten','gepensioneerde'],bron:'Wft'},
 {id:'pnx-227',thema:'pensioen',vraag:'Mag een klant zijn pensioen eerder laten ingaan om een hypotheek rond te krijgen?',antwoord:`Eerder ingaan levert direct pensioeninkomen op, maar de uitkering wordt levenslang lager. Dat kan de betaalbaarheid op lange termijn juist verslechteren. Bovendien is de keuze meestal onomkeerbaar. Leg de afweging en de gevolgen voor beide partners vast.`,tags:['hypotheek','vervroegen','afweging'],bron:''},
 {id:'pnx-228',thema:'pensioen',vraag:'Hoe toets ik de hypotheek als een partner overlijdt na pensionering?',antwoord:`Na overlijden daalt het inkomen door de AOW voor alleenstaanden en het nabestaandenpensioen. Vaak vervalt een deel van het pensioen van de overledene. Maak een scenario met dit lagere inkomen tegenover de woonlasten. Leg de uitkomst en eventuele maatregelen vast.`,tags:['hypotheek','overlijden','pensioen'],bron:''},
 {id:'pnx-229',thema:'pensioen',vraag:'Kan pensioen in opbouw worden ingezet als zekerheid voor een lening?',antwoord:`Nee, pensioenaanspraken mogen in de regel niet worden verpand of vervreemd. Dat geldt ook voor de waarde in een premieregeling. De klant kan het opgebouwde vermogen dus niet als onderpand gebruiken. Ga uit van de toekomstige uitkering als inkomen.`,tags:['pensioen','verpanding','hypotheek'],bron:'Pensioenwet'},
 {id:'pnx-230',thema:'pensioen',vraag:'Wat gebeurt er met de renteaftrek na 30 jaar bij een oude hypotheek?',antwoord:`Renteaftrek voor een eigenwoningschuld is beperkt tot een periode van 30 jaar. Na afloop is er geen aftrek meer en kan de schuld onder voorwaarden naar box 3 gaan. Dit raakt vaak oudere klanten. Controleer de start van de aftrekperiode in het dossier.`,tags:['hypotheek','renteaftrek','30 jaar'],bron:'Wet IB 2001'},
 {id:'pnx-231',thema:'pensioen',vraag:'Hoe gaat een geldverstrekker om met een aflossingsvrije lening na de AOW-leeftijd?',antwoord:`Geldverstrekkers beoordelen of de lasten na de AOW-leeftijd betaalbaar zijn. Bij een aflossingsvrij deel kan de geldverstrekker vragen om een plan. Er zijn verschillen per geldverstrekker. Controleer de voorwaarden van de geldverstrekker.`,tags:['hypotheek','aflossingsvrij','aow'],bron:'AFM'},
 {id:'pnx-232',thema:'pensioen',vraag:'Telt het tweede inkomen van een gepensioneerde partner volledig mee?',antwoord:`In de leennormen telt het tweede inkomen volledig mee. Dat geldt ook bij pensioeninkomen van beide partners. Let wel op wat er gebeurt bij overlijden van een van beiden. Neem dat scenario mee in de betaalbaarheid.`,tags:['hypotheek','tweede inkomen','pensioen'],bron:'Nibud'},
 {id:'pnx-233',thema:'pensioen',vraag:'Kan een gepensioneerde extra lenen voor verduurzaming?',antwoord:`De leennormen geven extra leenruimte voor energiebesparende maatregelen. Voor een woning met label E, F of G gaat het in 2026 om €20.000. Voor C of D om €15.000 en voor A en B om €10.000. Bespreek of de besparing past bij het pensioeninkomen en controleer de voorwaarden van de geldverstrekker.`,tags:['hypotheek','verduurzaming','leenruimte'],bron:'Nibud'},
 {id:'pnx-234',thema:'pensioen',vraag:'Wat is de extra leenruimte voor energielabels bij aankoop van een seniorenwoning?',antwoord:`Bij aankoop geldt extra leenruimte afhankelijk van het label. Voor A of B is dat €10.000, voor A+ of A++ €20.000 en voor A+++ €25.000 in de normen voor 2026. Voor E, F of G is er geen extra ruimte. De klant moet de lasten wel kunnen dragen met het pensioeninkomen.`,tags:['hypotheek','energielabel','senior'],bron:'Nibud'},
 {id:'pnx-235',thema:'pensioen',vraag:'Hoe ga ik om met de alleenstaandencorrectie bij een weduwe die de woning wil houden?',antwoord:`De leennormen 2026 kennen een correctie voor alleenstaanden van €17.000. Dit kan de leenruimte van een alleenstaande vergroten. Controleer of en hoe de geldverstrekker deze correctie toepast, ook voor AOW-gerechtigden. Leg de berekening vast.`,tags:['hypotheek','alleenstaande','weduwe'],bron:'Nibud'},
 {id:'pnx-236',thema:'pensioen',vraag:'Wat als de hypotheek na pensionering alleen past met een lager pensioenscenario?',antwoord:`Gebruik het voorzichtige scenario als basis voor de toets. Past de hypotheek niet, bespreek dan aflossen, een lagere lening of extra sparen. Een te optimistisch scenario kan leiden tot betalingsproblemen. Leg de afweging en de keuze vast.`,tags:['hypotheek','scenario','pensioen'],bron:'AFM'},
 {id:'pnx-237',thema:'pensioen',vraag:'Hoe bespreek ik een looptijd die ver na de AOW-leeftijd doorloopt?',antwoord:`Een lening met een looptijd van 30 jaar loopt bij oudere klanten vaak door tot na de AOW-leeftijd. De lasten moeten dan uit het pensioeninkomen worden betaald. Laat zien hoe de lasten zich verhouden tot dat inkomen en wat de restschuld op de AOW-datum is. Leg de afweging van de klant vast.`,tags:['hypotheek','looptijd','aow'],bron:'AFM'},
 {id:'pnx-238',thema:'pensioen',vraag:'Wat betekent bijzonder partnerpensioen van een ex voor het hypotheekadvies van een nieuw stel?',antwoord:`Bij overlijden krijgt de nieuwe partner minder partnerpensioen, omdat een deel naar de ex gaat. De nieuwe partner moet de woonlasten dan met minder inkomen dragen. Een ORV of andere voorziening kan het tekort opvangen. Vraag het actuele partnerpensioen op en leg de afweging vast.`,tags:['hypotheek','bijzonder partnerpensioen','nabestaanden'],bron:'Pensioenwet'},
 {id:'pnx-239',thema:'pensioen',vraag:'Wat moet ik vastleggen bij hypotheekadvies voor een klant vlak voor pensioen?',antwoord:`Leg minimaal vast:
- het inkomen voor en na de AOW-leeftijd;
- de bronnen van de pensioengegevens;
- het gebruikte scenario;
- de afweging van de klant.
Bewaar ook de toetsing van de geldverstrekker.`,tags:['hypotheek','dossier','pensioen'],bron:'Wft'},
 {id:'pnx-240',thema:'pensioen',vraag:'Is aflossen met spaargeld verstandig voor een gepensioneerde?',antwoord:`Aflossen verlaagt de lasten en de rente. Het verlaagt ook de liquiditeit van de klant. Een gepensioneerde heeft vaak minder mogelijkheden om later weer te lenen. Zorg dat er voldoende buffer overblijft en leg de afweging vast.`,tags:['hypotheek','aflossen','liquiditeit'],bron:''},
 {id:'pnx-241',thema:'pensioen',vraag:'Wat is het risico van een renteherziening na pensionering?',antwoord:`Bij een renteherziening kunnen de lasten stijgen. Met een vast pensioeninkomen is dat moeilijker op te vangen. Bespreek de rentevaste periode in relatie tot de pensioendatum. Leg de keuze en de risicobereidheid vast.`,tags:['hypotheek','rente','pensioen'],bron:''},
 {id:'pnx-242',thema:'pensioen',vraag:'Hoe ga ik om met een klant die zijn pensioen wil gebruiken om een hypotheek voor een kind te verstrekken?',antwoord:`Een familiehypotheek kan een kind helpen, maar het geld zit vast. De ouders moeten zelf voldoende inkomen en buffer houden. Leg de afspraken schriftelijk vast en betrek een notaris of fiscalist. Bespreek de risico's als het kind niet kan betalen.`,tags:['hypotheek','familiehypotheek','risico'],bron:''},
 {id:'pnx-243',thema:'pensioen',vraag:'Kan een pensioen in betaling als inkomen gelden voor de NHG?',antwoord:`Een pensioen in betaling geldt als inkomen voor de toets. NHG heeft eigen normen en voorwaarden. De grens voor NHG verandert jaarlijks. Controleer de actuele voorwaarden en grenzen bij NHG.`,tags:['hypotheek','nhg','pensioen'],bron:'NHG'},
 {id:'pnx-244',thema:'pensioen',vraag:'Wat is een veelgemaakte fout bij hypotheekadvies rond pensioen?',antwoord:`Adviseurs kijken soms alleen naar het huidige inkomen. Ze vergeten de daling bij pensionering of overlijden. Ook wordt het te bereiken pensioen te snel als zeker gezien. Werk met realistische scenario's en leg ze vast.`,tags:['hypotheek','pensioen','fouten'],bron:'AFM'},
 {id:'pnx-245',thema:'pensioen',vraag:'Hoe verwerk ik een tijdelijke overbruggingsuitkering in de hypotheektoets?',antwoord:`Een tijdelijke uitkering telt alleen mee voor de duur ervan. Daarna moet de hypotheek betaalbaar zijn met het blijvende inkomen. Geldverstrekkers hanteren eigen regels. Controleer de voorwaarden van de geldverstrekker.`,tags:['hypotheek','overbrugging','toets'],bron:''},
 {id:'pnx-246',thema:'pensioen',vraag:'Waar let ik op als een gepensioneerde een tweede woning wil kopen?',antwoord:`Een tweede woning is geen eigen woning en valt in box 3. De rente is dan niet aftrekbaar als eigenwoningrente. De lasten moeten worden gedragen uit pensioen, huur of vermogen. Controleer de voorwaarden van de geldverstrekker en leg de risico's vast.`,tags:['tweede woning','box 3','gepensioneerde'],bron:'Wet IB 2001'},
 {id:'pnx-247',thema:'pensioen',vraag:'Wat moet ik doen als een gepensioneerde klant betalingsachterstanden krijgt?',antwoord:`Neem snel contact op met de geldverstrekker om oplossingen te bespreken. Kijk naar mogelijkheden zoals een andere aflosvorm of verkoop. Verwijs bij grotere problemen naar schuldhulp. Leg de stappen en afspraken vast.`,tags:['hypotheek','achterstand','senior'],bron:''},
 {id:'pnx-248',thema:'pensioen',vraag:'Telt een restschuld uit de restschuldregeling mee na pensionering?',antwoord:`Voor restschulden die zijn ontstaan tussen 29-10-2012 en 31-12-2017 kan de rente onder voorwaarden maximaal 15 jaar aftrekbaar zijn. De aflossing en rente van de restschuld lopen vaak door tot na de pensioendatum. Dat drukt op het pensioeninkomen. Neem de restschuld en het einde van de aftrektermijn mee in de betaalbaarheidsanalyse.`,tags:['hypotheek','restschuld','pensioen'],bron:'Wet IB 2001'},
 {id:'pnx-249',thema:'pensioen',vraag:'Hoe beïnvloedt een lening van de BV aan de DGA de pensioenverplichting?',antwoord:`Als de BV geld uitleent aan de DGA, zit dat geld niet meer vrij in de BV. De BV moet de pensioenverplichting toch kunnen nakomen. Een grote vordering op de DGA kan de zekerheid van het pensioen verkleinen. Beoordeel de liquiditeit van de BV en leg de risico's vast.`,tags:['dga','lening','pensioenverplichting'],bron:''},
 {id:'pnx-250',thema:'pensioen',vraag:'Wanneer verwijs ik een klant door naar een pensioenspecialist?',antwoord:`Verwijs door als de situatie buiten je eigen vakbekwaamheid valt. Denk aan eigen beheer, internationale pensioenen of complexe scheidingen. Ook fiscale structuren vragen soms een specialist. Leg in het dossier vast naar wie je hebt verwezen en waarom.`,tags:['doorverwijzen','specialist','vakbekwaamheid'],bron:'Wft'},
]);
